SS_MSG(enter_render_help,
    EN("Make a photo or a video of this model: lay out a camera move, choose a lens and write the file. Every other open model can take part."),
    JA("このモデルの写真や動画を作ります。カメラの動きを組み、レンズを選び、ファイルに書き出します。開いている他のモデルも登場させられます。"),
    ZH_HANS("为此模型制作照片或视频：安排相机运动、选择镜头并写出文件。其他已打开的模型也可以参与。"),
    ZH_HANT("為此模型製作相片或影片：安排相機運動、選擇鏡頭並寫出檔案。其他已開啟的模型也可以參與。"),
    KO("이 모델의 사진이나 동영상을 만듭니다. 카메라 움직임을 짜고 렌즈를 고른 뒤 파일로 씁니다. 열려 있는 다른 모델도 함께 쓸 수 있습니다."),
    DE("Ein Foto oder Video dieses Modells machen: eine Kamerafahrt anlegen, ein Objektiv wählen und die Datei schreiben. Jedes andere geöffnete Modell kann mitspielen."),
    FR("Faire une photo ou une vidéo de ce modèle : composer un mouvement de caméra, choisir un objectif et écrire le fichier. Tout autre modèle ouvert peut y participer."),
    ES("Hacer una foto o un vídeo de este modelo: trazar un movimiento de cámara, elegir un objetivo y escribir el archivo. Cualquier otro modelo abierto puede participar."),
    PT("Fazer uma foto ou um vídeo deste modelo: montar um movimento de câmera, escolher uma lente e gravar o arquivo. Qualquer outro modelo aberto pode participar."),
    IT("Fare una foto o un video di questo modello: tracciare un movimento di camera, scegliere un obiettivo e scrivere il file. Ogni altro modello aperto può partecipare."),
    NL("Een foto of video van dit model maken: een camerabeweging uitzetten, een lens kiezen en het bestand schrijven. Elk ander geopend model kan meedoen."),
    RU("Сделать фото или видео этой модели: задать движение камеры, выбрать объектив и записать файл. В нём могут участвовать и другие открытые модели."),
    TR("Bu modelin fotoğrafını ya da videosunu yapın: bir kamera hareketi kurun, bir lens seçin ve dosyayı yazın. Açık olan diğer modeller de yer alabilir."));

SS_MSG(edit_to_render,
    EN("Render a photo or a video"),
    JA("写真・動画をレンダリング"),
    ZH_HANS("渲染照片或视频"),
    ZH_HANT("算繪相片或影片"),
    KO("사진 또는 동영상 렌더링"),
    DE("Foto oder Video rendern"),
    FR("Rendre une photo ou une vidéo"),
    ES("Renderizar una foto o un vídeo"),
    PT("Renderizar uma foto ou um vídeo"),
    IT("Render di una foto o un video"),
    NL("Foto of video renderen"),
    RU("Рендер фото или видео"),
    TR("Fotoğraf ya da video render et"));

SS_MSG(edit_to_render_help,
    EN("Go to render mode with this model. The edit stays open behind it, so what you deleted stays deleted in the render."),
    JA("このモデルでレンダリングモードに入ります。編集は裏で開いたままなので、削除したものはレンダリングでも消えたままです。"),
    ZH_HANS("用此模型进入渲染模式。编辑会在后台保持打开，所以删掉的内容在渲染中仍然是删掉的。"),
    ZH_HANT("用此模型進入算繪模式。編輯會在背景保持開啟，所以刪掉的內容在算繪中仍然是刪掉的。"),
    KO("이 모델로 렌더링 모드에 들어갑니다. 편집은 뒤에 열린 채로 남아, 지운 것은 렌더링에서도 지워진 채입니다."),
    DE("Mit diesem Modell in den Render-Modus wechseln. Die Bearbeitung bleibt dahinter offen: Was gelöscht wurde, bleibt auch im Render gelöscht."),
    FR("Passer en mode rendu avec ce modèle. L'édition reste ouverte derrière : ce qui a été supprimé reste supprimé dans le rendu."),
    ES("Pasar al modo de renderizado con este modelo. La edición sigue abierta detrás: lo que se borró sigue borrado en el render."),
    PT("Ir para o modo de renderização com este modelo. A edição continua aberta por trás: o que foi apagado continua apagado na renderização."),
    IT("Passa alla modalità render con questo modello. La modifica resta aperta dietro: ciò che è stato eliminato resta eliminato nel render."),
    NL("Met dit model naar de rendermodus. De bewerking blijft erachter open: wat verwijderd is, blijft ook in de render verwijderd."),
    RU("Перейти в режим рендера с этой моделью. Правка остаётся открытой позади: удалённое останется удалённым и в рендере."),
    TR("Bu modelle render moduna geçin. Düzenleme arkada açık kalır; silinenler render'da da silinmiş kalır."));

