SS_MSG(to_edit_help,
    EN("Go to the editor with this model; the camera move is kept and comes back when you return."),
    JA("このモデルでエディターに移ります。カメラの動きは保たれ、戻ると元に戻ります。"),
    ZH_HANS("用此模型转到编辑器；相机运动会保留，回来时仍在。"),
    ZH_HANT("用此模型轉到編輯器；相機運動會保留，回來時仍在。"),
    KO("이 모델로 편집기로 갑니다. 카메라 움직임은 그대로 남아 돌아오면 다시 나타납니다."),
    DE("Mit diesem Modell in den Editor wechseln; die Kamerafahrt bleibt erhalten und ist beim Zurückkommen wieder da."),
    FR("Passer à l'éditeur avec ce modèle ; le mouvement de caméra est conservé et revient au retour."),
    ES("Ir al editor con este modelo; el movimiento de cámara se conserva y vuelve al regresar."),
    PT("Ir para o editor com este modelo; o movimento de câmera é mantido e volta quando você voltar."),
    IT("Passa all'editor con questo modello; il movimento di camera resta e torna al ritorno."),
    NL("Met dit model naar de editor; de camerabeweging blijft bewaard en is er weer bij terugkomst."),
    RU("Перейти в редактор с этой моделью; движение камеры сохранится и вернётся, когда вы вернётесь."),
    TR("Bu modelle düzenleyiciye geçin; kamera hareketi korunur ve geri döndüğünüzde yerindedir."));

