SS_MSG(train_edit_help,
    EN("Open the model this run saved in the editor, to delete floaters or move it."),
    JA("この実行が保存したモデルをエディターで開き、浮遊物を消したり位置を直したりします。"),
    ZH_HANS("在编辑器中打开本次运行保存的模型，删除漂浮物或移动它。"),
    ZH_HANT("在編輯器中開啟本次執行儲存的模型，刪除漂浮物或移動它。"),
    KO("이번 실행이 저장한 모델을 편집기로 열어 떠다니는 조각을 지우거나 옮깁니다."),
    DE("Das von diesem Lauf gespeicherte Modell im Editor öffnen, um Floater zu löschen oder es zu verschieben."),
    FR("Ouvrir dans l'éditeur le modèle enregistré par cette exécution, pour supprimer des artefacts flottants ou le déplacer."),
    ES("Abrir en el editor el modelo que guardó esta ejecución, para borrar elementos flotantes o moverlo."),
    PT("Abrir no editor o modelo que esta execução salvou, para apagar elementos flutuantes ou movê-lo."),
    IT("Apri nell'editor il modello salvato da questa esecuzione, per eliminare elementi fluttuanti o spostarlo."),
    NL("Het door deze run opgeslagen model in de editor openen, om zwevende artefacten te verwijderen of het te verplaatsen."),
    RU("Открыть модель этого запуска в редакторе, чтобы удалить «плавающие» сплаты или сдвинуть её."),
    TR("Bu çalıştırmanın kaydettiği modeli düzenleyicide açın; havada kalan parçaları silmek ya da taşımak için."));


