SS_MSG(quick_orbit_help,
    EN("Create a closed orbit with 8 keyframes at the current distance and height. A straight-down view tilts to 30°; all cameras look at the pivot."),
    JA("現在の距離と高さで8キーフレームの周回を作ります。真下向きなら30°に傾け、全カメラを旋回中心へ向けます。"),
    ZH_HANS("按当前距离和高度创建 8 个关键帧的闭合环绕。俯视时倾斜至 30°，所有相机朝向旋转中心。"),
    ZH_HANT("按目前距離和高度建立 8 個關鍵影格的閉合環繞。俯視時傾斜至 30°，所有相機朝向旋轉中心。"),
    KO("현재 거리와 높이에서 키프레임 8개의 닫힌 궤도를 만듭니다. 수직 아래 시점은 30°로 기울고 모두 피벗을 바라봅니다."),
    DE("Geschlossenen Orbit mit 8 Keyframes in aktueller Entfernung und Höhe erstellen. Senkrechter Blick wird auf 30° geneigt; alle blicken zum Drehpunkt."),
    FR("Crée une orbite fermée de 8 images clés à distance et hauteur actuelles. Vue verticale inclinée à 30° ; regards vers le pivot."),
    ES("Crea una órbita cerrada de 8 claves a la distancia y altura actuales. Inclina la vista vertical a 30°; todas miran al pivote."),
    PT("Cria órbita fechada com 8 quadros-chave na distância e altura atuais. Inclina a vista vertical a 30°; todos olham o pivô."),
    IT("Crea un’orbita chiusa di 8 chiavi a distanza e altezza attuali. Inclina la vista verticale a 30°; tutte guardano il perno."),
    NL("Maak een gesloten baan met 8 keyframes op huidige afstand en hoogte. Een blik recht omlaag kantelt naar 30°; alle kijken naar het draaipunt."),
    RU("Создаёт замкнутую орбиту из 8 ключей на текущем расстоянии и высоте. Вид сверху наклоняет до 30°; все камеры смотрят на центр."),
    TR("Güncel uzaklık ve yükseklikte 8 anahtarlı kapalı yörünge oluşturur. Dikey aşağı bakış 30°’ye eğilir; tüm kameralar pivota bakar."));

