SS_MSG(quick_capture_help,
    EN("Keyframes along the path the photos were taken on, from the dataset's own cameras."),
    JA("データセット自身のカメラから、写真が撮られた経路に沿ったキーフレームを作ります。"),
    ZH_HANS("根据数据集本身的相机，沿拍照时走过的路径生成关键帧。"),
    ZH_HANT("根據資料集本身的相機，沿拍照時走過的路徑產生關鍵影格。"),
    KO("데이터셋 자체의 카메라를 이용해 사진을 찍은 경로를 따라 키프레임을 만듭니다."),
    DE("Keyframes entlang des Wegs, auf dem die Fotos gemacht wurden, aus den Kameras des Datensatzes selbst."),
    FR("Des images clés le long du chemin où les photos ont été prises, à partir des caméras du jeu de données."),
    ES("Fotogramas clave a lo largo del camino donde se tomaron las fotos, a partir de las cámaras del propio conjunto de datos."),
    PT("Quadros-chave ao longo do caminho em que as fotos foram tiradas, a partir das câmeras do próprio conjunto de dados."),
    IT("Fotogrammi chiave lungo il percorso in cui sono state scattate le foto, dalle camere del set di dati stesso."),
    NL("Keyframes langs het pad waarop de foto's zijn gemaakt, uit de camera's van de dataset zelf."),
    RU("Ключевые кадры вдоль пути, по которому снимались фото, — по камерам самого набора данных."),
    TR("Veri setinin kendi kameralarından, fotoğrafların çekildiği yol boyunca anahtar kareler."));

SS_MSG(quick_capture_none,
    EN("Needs a reconstruction with cameras: add the dataset as a model first."),
    JA("カメラを含む再構成が必要です。先にデータセットをモデルとして追加してください。"),
    ZH_HANS("需要带相机的重建：请先把数据集作为模型添加。"),
    ZH_HANT("需要帶相機的重建：請先把資料集作為模型加入。"),
    KO("카메라가 있는 재구성이 필요합니다. 먼저 데이터셋을 모델로 추가하세요."),
    DE("Braucht eine Rekonstruktion mit Kameras: zuerst den Datensatz als Modell hinzufügen."),
    FR("Il faut une reconstruction avec des caméras : ajoutez d'abord le jeu de données comme modèle."),
    ES("Necesita una reconstrucción con cámaras: añada primero el conjunto de datos como modelo."),
    PT("Precisa de uma reconstrução com câmeras: adicione primeiro o conjunto de dados como modelo."),
    IT("Serve una ricostruzione con camere: aggiungi prima il set di dati come modello."),
    NL("Vereist een reconstructie met camera's: voeg eerst de dataset als model toe."),
    RU("Нужна реконструкция с камерами: сначала добавьте набор данных как модель."),
    TR("Kameralı bir yeniden oluşturma gerekir: önce veri kümesini model olarak ekleyin."));

