SS_MSG(quick_fly_help,
    EN("Fly the camera yourself -- with the mouse, the keyboard or a gamepad, in any navigation mode;\nFree fly is made for it -- and the flight becomes keyframes. Enter keeps it, Esc throws it away."),
    JA("マウス、キーボード、ゲームパッドで自分でカメラを飛ばします。 どの操作モードでも使えますが、フリーフライ向きです。\n飛んだ経路がキーフレームになります。 Enter で残し、Esc で捨てます。"),
    ZH_HANS("用鼠标、键盘或手柄亲自驾驶相机飞行——任何导航模式都行，自由飞行最合适——飞过的路线会变成关键帧。\nEnter 保留，Esc 丢弃。"),
    ZH_HANT("用滑鼠、鍵盤或手把親自駕駛相機飛行——任何導航模式都行，自由飛行最合適——飛過的路線會變成關鍵影格。\nEnter 保留，Esc 丟棄。"),
    KO("마우스, 키보드, 게임패드로 카메라를 직접 날립니다. 어떤 탐색 모드에서도 되지만 자유 비행이 가장 알맞습니다.\n비행한 경로가 키프레임이 됩니다. Enter는 남기고 Esc는 버립니다."),
    DE("Die Kamera selbst fliegen – mit Maus, Tastatur oder Gamepad, in jedem Navigationsmodus;\nFreier Flug ist dafür gemacht –, und der Flug wird zu Keyframes. Enter behält ihn, Esc verwirft ihn."),
    FR("Pilotez la caméra vous-même – à la souris, au clavier ou à la manette, dans n'importe quel mode de navigation ;\nle vol libre est fait pour cela – et le vol devient des images clés. Entrée le garde, Échap le jette."),
    ES("Vuele la cámara usted mismo –con el ratón, el teclado o un mando, en cualquier modo de navegación;\n- el vuelo libre está hecho para ello– y el vuelo se convierte en fotogramas clave.\n- Enter lo guarda, Esc lo descarta."),
    PT("Pilote a câmera você mesmo – com o mouse, o teclado ou um controle, em qualquer modo de navegação;\no voo livre é feito para isso – e o voo vira quadros-chave. Enter o guarda, Esc o descarta."),
    IT("Pilota tu la camera – con il mouse, la tastiera o un gamepad, in qualsiasi modalità di navigazione;\nil volo libero è fatto apposta – e il volo diventa fotogrammi chiave. Invio lo tiene, Esc lo scarta."),
    NL("Vlieg de camera zelf – met de muis, het toetsenbord of een gamepad, in elke navigatiemodus;\nvrij vliegen is ervoor gemaakt – en de vlucht wordt keyframes. Enter bewaart hem, Esc gooit hem weg."),
    RU("Проведите камеру сами — мышью, клавиатурой или геймпадом, в любом режиме навигации;\nдля этого создан свободный полёт, — и полёт станет ключевыми кадрами. Enter сохраняет его, Esc отбрасывает."),
    TR("Kamerayı kendiniz uçurun – fareyle, klavyeyle ya da oyun kumandasıyla, herhangi bir gezinme kipinde;\nserbest uçuş tam bunun için – ve uçuş anahtar karelere dönüşür. Enter tutar, Esc atar."));

