SS_MSG(fly_hint,
    EN("Flying: move the view with the mouse, WASD and E/Q, or a gamepad. Enter keeps the flight, Esc throws it away."),
    JA("飛行中: マウス、WASD と E/Q、またはゲームパッドでビューを動かします。Enter で飛行を残し、Esc で捨てます。"),
    ZH_HANS("飞行中：用鼠标、WASD 和 E/Q 或手柄移动视图。Enter 保留这次飞行，Esc 丢弃。"),
    ZH_HANT("飛行中：用滑鼠、WASD 和 E/Q 或手把移動視圖。Enter 保留這次飛行，Esc 丟棄。"),
    KO("비행 중: 마우스, WASD와 E/Q, 또는 게임패드로 뷰를 움직입니다. Enter는 비행을 남기고 Esc는 버립니다."),
    DE("Im Flug: Die Ansicht mit Maus, WASD und E/Q oder einem Gamepad bewegen. Enter behält den Flug, Esc verwirft ihn."),
    FR("En vol : bougez la vue à la souris, avec WASD et E/Q, ou à la manette. Entrée garde le vol, Échap le jette."),
    ES("En vuelo: mueva la vista con el ratón, WASD y E/Q, o un mando. Enter guarda el vuelo, Esc lo descarta."),
    PT("Em voo: mova a vista com o mouse, WASD e E/Q, ou um controle. Enter guarda o voo, Esc o descarta."),
    IT("In volo: muovi la vista con il mouse, WASD ed E/Q, o un gamepad. Invio tiene il volo, Esc lo scarta."),
    NL("In de lucht: beweeg het beeld met de muis, WASD en E/Q, of een gamepad. Enter bewaart de vlucht, Esc gooit hem weg."),
    RU("В полёте: двигайте вид мышью, WASD и E/Q или геймпадом. Enter сохраняет полёт, Esc отбрасывает."),
    TR("Uçuşta: görünümü fareyle, WASD ve E/Q ile ya da oyun kumandasıyla hareket ettirin. Enter uçuşu tutar, Esc atar."));

