SS_MSG(fit_timing_help,
    EN("At 1 the move keeps your pace as you flew it, stops and all.\n- At 0 it goes at one steady pace, which rushes through tight spots and dawdles in open ones.\n- Between the two, the stops drop out and the slow parts stay a little slow."),
    JA("1 では飛んだときのペースを、止まった所も含めてそのまま保ちます。\n- 0 では一定のペースで進み、狭い所は急ぎ、開けた所はゆっくりになります。\n- その中間では止まった所が抜け、遅かった所は少し遅いまま残ります。"),
    ZH_HANS("为 1 时，运动保持你飞行时的节奏，停顿也保留。 为 0 时，以同一速度前进，狭窄处会显得匆忙，开阔处则显得拖沓。\n两者之间，停顿被去掉，慢的部分仍稍慢一些。"),
    ZH_HANT("為 1 時，運動保持你飛行時的節奏，停頓也保留。 為 0 時，以同一速度前進，狹窄處會顯得匆忙，開闊處則顯得拖沓。\n兩者之間，停頓被去掉，慢的部分仍稍慢一些。"),
    KO("1: 멈춤을 포함해 비행 속도 그대로. 0: 일정 속도로 좁은 곳은 빠르게, 넓은 곳은 느리게 지납니다.\n중간 값: 멈춤은 없애고 느린 구간은 조금 느리게 유지합니다."),
    DE("Bei 1 behält die Bewegung dein Tempo, wie du geflogen bist, mit allen Halten.\n- Bei 0 geht sie in einem gleichmäßigen Tempo, das enge Stellen hetzt und offene in die Länge zieht.\n- Dazwischen fallen die Halte weg, und langsame Stellen bleiben etwas langsam."),
    FR("À 1, le mouvement garde votre rythme de vol, arrêts compris.\n- À 0, il avance à un rythme constant, qui bouscule les passages étroits et s'attarde dans les espaces ouverts.\n- Entre les deux, les arrêts disparaissent et les passages lents restent un peu lents."),
    ES("En 1, el movimiento conserva el ritmo con el que voló, paradas incluidas.\n- En 0, avanza a un ritmo constante, que apresura los pasos estrechos y se demora en los abiertos.\n- Entre ambos, las paradas desaparecen y las partes lentas siguen algo lentas."),
    PT("Em 1, o movimento mantém o ritmo do seu voo, com paradas e tudo.\n- Em 0, segue num ritmo constante, que apressa os trechos apertados e se arrasta nos abertos.\n- Entre os dois, as paradas somem e os trechos lentos continuam um pouco lentos."),
    IT("A 1 il movimento mantiene il ritmo con cui hai volato, soste comprese.\n- A 0 procede a un ritmo costante, che mette fretta nei passaggi stretti e si attarda in quelli aperti.\n- In mezzo, le soste spariscono e i tratti lenti restano un po' lenti."),
    NL("Bij 1 houdt de beweging jouw tempo aan zoals je vloog, stops en al.\n- Bij 0 gaat hij in één gelijk tempo, dat door krappe stukken jaagt en in open stukken treuzelt.\n- Daartussen vallen de stops weg en blijven trage stukken wat traag."),
    RU("При 1 движение сохраняет темп вашего полёта, со всеми остановками.\n- При 0 идёт в одном ровном темпе, который торопит в тесных местах и тянется в открытых.\n- Между ними остановки выпадают, а медленные участки остаются немного медленными."),
    TR("1'de hareket uçtuğunuz hızı duraklarıyla birlikte korur. 0'da tek bir sabit hızla gider;\n- dar yerlerde aceleye getirir, açık yerlerde oyalanır.\n- İkisinin arasında duraklar düşer ve yavaş kısımlar biraz yavaş kalır."));

