SS_MSG(fit_detail_help,
    EN("More follows the flight more closely, with more keyframes; less smooths it out with fewer."),
    JA("多いほどキーフレームを増やして飛行に近づけ、少ないほどキーフレームを減らして滑らかにします。"),
    ZH_HANS("越多，越贴近飞行，关键帧也越多；越少，越平滑，关键帧也越少。"),
    ZH_HANT("越多，越貼近飛行，關鍵影格也越多；越少，越平滑，關鍵影格也越少。"),
    KO("많을수록 키프레임을 늘려 비행에 가깝게 따르고, 적을수록 키프레임을 줄여 매끄럽게 합니다."),
    DE("Mehr folgt dem Flug genauer, mit mehr Keyframes; weniger glättet ihn mit weniger."),
    FR("Plus suit le vol de plus près, avec plus d'images clés ; moins le lisse avec moins."),
    ES("Más sigue el vuelo más de cerca, con más fotogramas clave; menos lo suaviza con menos."),
    PT("Mais segue o voo mais de perto, com mais quadros-chave; menos o suaviza com menos."),
    IT("Di più segue il volo più da vicino, con più fotogrammi chiave; di meno lo ammorbidisce con meno."),
    NL("Meer volgt de vlucht nauwer, met meer keyframes; minder strijkt hem glad met minder."),
    RU("Больше — ближе к полёту, с большим числом ключевых кадров; меньше — сглаживает его меньшим числом."),
    TR("Fazlası uçuşu daha yakından, daha çok anahtar kareyle izler; azı onu daha az kareyle yumuşatır."));

