SS_MSG(keys_space_evenly_help,
    EN("Spread the keyframes at equal intervals over this many seconds.\nAt constant speed the path decides when each keyframe is passed, so this turns constant speed off."),
    JA("キーフレームをこの秒数の中で等間隔に並べます。\n一定の速さでは各キーフレームを通る時刻を経路が決めるので、これを押すと一定の速さはオフになります。"),
    ZH_HANS("在这么多秒内把关键帧等间隔排开。匀速时经过每个关键帧的时间由路径决定，所以这会关闭匀速。"),
    ZH_HANT("在這麼多秒內把關鍵影格等間隔排開。等速時經過每個關鍵影格的時間由路徑決定，所以這會關閉等速。"),
    KO("키프레임을 이 초 동안 같은 간격으로 펼칩니다.\n일정한 속도에서는 각 키프레임을 지나는 시각을 경로가 정하므로, 이것을 누르면 일정한 속도가 꺼집니다."),
    DE("Die Keyframes gleichmäßig über so viele Sekunden verteilen.\n- Bei gleichmäßigem Tempo bestimmt der Weg, wann jeder Keyframe passiert wird;\n- deshalb schaltet dies das gleichmäßige Tempo aus."),
    FR("Répartit les images clés à intervalles égaux sur cette durée. Désactive la vitesse constante, qui fixe les temps selon le trajet."),
    ES("Distribuye las claves a intervalos iguales en esta duración. Desactiva la velocidad constante, que fija los tiempos según el recorrido."),
    PT("Distribui os quadros-chave em intervalos iguais nesta duração. Desliga a velocidade constante, que fixa tempos conforme o percurso."),
    IT("Distribuisce le chiavi a intervalli uguali in questa durata. Disattiva la velocità costante, che fissa i tempi in base al percorso."),
    NL("De keyframes gelijkmatig over zoveel seconden verdelen. Bij constante snelheid bepaalt het pad wanneer elke keyframe wordt gepasseerd, dus dit zet constante snelheid uit."),
    RU("Расставить ключевые кадры через равные промежутки на столько секунд.\nПри постоянной скорости момент прохождения каждого кадра задаёт путь, поэтому это выключает постоянную скорость."),
    TR("Anahtar kareleri bu kadar saniyeye eşit aralıklarla yay.\nSabit hızda her anahtar karenin ne zaman geçileceğini yol belirler; bu yüzden bu, sabit hızı kapatır."));

SS_MSG(space_evenly_speed,
    EN("Constant speed is off: the keyframes are now passed at equal intervals."),
    JA("一定の速さをオフにしました。キーフレームは等間隔で通過します。"),
    ZH_HANS("匀速已关闭：现在按相等的间隔经过各关键帧。"),
    ZH_HANT("等速已關閉：現在按相等的間隔經過各關鍵影格。"),
    KO("일정한 속도를 껐습니다. 이제 키프레임을 같은 간격으로 지납니다."),
    DE("Gleichmäßiges Tempo ist aus: Die Keyframes werden jetzt in gleichen Abständen passiert."),
    FR("Vitesse constante désactivée : les images clés sont maintenant franchies à intervalles égaux."),
    ES("Velocidad constante desactivada: ahora se pasa por los fotogramas clave a intervalos iguales."),
    PT("Velocidade constante desligada: os quadros-chave agora são atravessados em intervalos iguais."),
    IT("Velocità costante disattivata: ora i fotogrammi chiave si attraversano a intervalli uguali."),
    NL("Constante snelheid staat uit: de keyframes worden nu met gelijke tussenpozen gepasseerd."),
    RU("Постоянная скорость выключена: теперь ключевые кадры проходятся через равные промежутки."),
    TR("Sabit hız kapalı: anahtar karelerden artık eşit aralıklarla geçiliyor."));

