SS_MSG(key_camera_size_help,
    EN("Keyframe camera display size relative to similar viewer cameras, never below the dataset’s size. Scene size stays equal at every distance."),
    JA("同種のビューアカメラに対するキーフレームカメラの表示サイズ。データセットのサイズ以上で、距離によらずシーン内の大きさは同じ。"),
    ZH_HANS("关键帧相机相对同类查看器相机的显示尺寸，不小于数据集相机。所有相机在场景中的大小相同，与距离无关。"),
    ZH_HANT("關鍵影格相機相對同類檢視器相機的顯示尺寸，不小於資料集相機。所有相機在場景中的大小相同，與距離無關。"),
    KO("비슷한 뷰어 카메라 대비 키프레임 카메라 표시 크기입니다. 데이터셋 크기 이상이며, 거리와 무관하게 장면 크기가 같습니다."),
    DE("Keyframe-Kameragröße relativ zu ähnlichen Viewer-Kameras, mindestens Datensatzgröße. Die Szenengröße ist bei jeder Entfernung gleich."),
    FR("Taille des caméras clés relative aux caméras similaires, au moins celle du jeu de données. Même taille dans la scène quelle que soit la distance."),
    ES("Tamaño de cámaras clave relativo a las similares, no menor que el del conjunto. Igual tamaño en escena a cualquier distancia."),
    PT("Tamanho das câmeras-chave relativo às semelhantes, não menor que o do conjunto. Mesmo tamanho na cena em qualquer distância."),
    IT("Dimensione camere chiave relativa a quelle simili, non inferiore al dataset. Stessa dimensione nella scena a ogni distanza."),
    NL("Keyframe-cameragrootte relatief aan vergelijkbare viewercamera’s, minstens datasetgrootte. Gelijke scènegrootte op elke afstand."),
    RU("Размер камер ключей относительно похожих камер просмотрщика, не меньше камер набора. Размер в сцене одинаков при любой дальности."),
    TR("Anahtar kamera boyutu benzer görüntüleyici kameralara göredir, veri kümesinden küçük olmaz. Sahnedeki boyut her uzaklıkta aynıdır."));


