SS_MSG(lens_auto_help,
    EN("On: the zoom and the distortion glide between the nearest keyframes before and after this one that have a lens of their own. Off: this keyframe has its own."),
    JA("オンにすると、前後で最も近い、独自のレンズを持つキーフレームの間で、ズームと歪みが滑らかに移ります。オフにすると、このキーフレームが独自のレンズを持ちます。"),
    ZH_HANS("开启：变焦和畸变在前后最近的、有自己镜头的关键帧之间平滑过渡。关闭：此关键帧有自己的镜头。"),
    ZH_HANT("開啟：變焦和畸變在前後最近的、有自己鏡頭的關鍵影格之間平滑過渡。關閉：此關鍵影格有自己的鏡頭。"),
    KO("켜면 줌과 왜곡이 앞뒤로 가장 가까운, 자기 렌즈를 가진 키프레임 사이에서 부드럽게 옮겨 갑니다. 끄면 이 키프레임이 자기 렌즈를 가집니다."),
    DE("An: Zoom und Verzeichnung gleiten zwischen dem nächsten Keyframe davor und danach, der ein eigenes Objektiv hat. Aus: Dieser Keyframe hat ein eigenes."),
    FR("Activé : le zoom et la distorsion glissent entre les images clés les plus proches, avant et après, qui ont leur propre objectif. Désactivé : cette image clé a le sien."),
    ES("Activado: el zoom y la distorsión se deslizan entre los fotogramas clave más cercanos, antes y después, que tienen objetivo propio. Desactivado: este tiene el suyo."),
    PT("Ligado: o zoom e a distorção deslizam entre os quadros-chave mais próximos, antes e depois, que têm lente própria. Desligado: este tem a sua."),
    IT("Attivato: zoom e distorsione scivolano tra i fotogrammi chiave più vicini, prima e dopo, che hanno un obiettivo proprio. Disattivato: questo ha il suo."),
    NL("Aan: zoom en vertekening glijden tussen de dichtstbijzijnde keyframes ervoor en erna die een eigen lens hebben. Uit: deze keyframe heeft een eigen lens."),
    RU("Вкл.: зум и дисторсия плавно меняются между ближайшими ключевыми кадрами до и после этого, у которых свой объектив. Выкл.: у этого кадра свой."),
    TR("Açık: yakınlaştırma ve bozulma, öncesinde ve sonrasında kendi lensi olan en yakın anahtar kareler arasında kayar. Kapalı: bu anahtar karenin kendi lensi olur."));

