SS_MSG(motion_curve_help,
    EN("- Smooth spline: smoothly varying speed and acceleration through every keyframe.\n- Catmull-Rom: moving a keyframe affects only nearby path segments.\n- Straight lines: turn at each keyframe."),
    JA("- 滑らかなスプライン：全キーフレームで速度と加速度が滑らかに変化。\n- Catmull-Rom：キーフレームの移動が近くの経路だけに影響。\n- 直線：各キーフレームで方向転換。"),
    ZH_HANS("- 平滑样条：速度和加速度平滑地通过各关键帧。\n- Catmull-Rom：移动关键帧只影响附近路径。\n- 直线：在每个关键帧转向。"),
    ZH_HANT("- 平滑樣條：速度和加速度平滑地通過各關鍵影格。\n- Catmull-Rom：移動關鍵影格只影響附近路徑。\n- 直線：在每個關鍵影格轉向。"),
    KO("- 부드러운 스플라인: 모든 키프레임에서 속도와 가속도가 매끄럽게 변합니다.\n- Catmull-Rom: 키프레임 이동은 근처 경로만 바꿉니다.\n- 직선: 키프레임마다 방향을 바꿉니다."),
    DE("- Glatter Spline: Geschwindigkeit und Beschleunigung ändern sich durch alle Keyframes glatt.\n- Catmull-Rom: Keyframe-Verschiebung wirkt nur auf benachbarte Wegstücke.\n- Geraden: an jedem Keyframe abbiegen."),
    FR("- Spline lisse : vitesse et accélération varient sans à-coup à chaque clé.\n- Catmull-Rom : déplacer une clé ne modifie que le trajet proche.\n- Lignes droites : tournent à chaque clé."),
    ES("- Spline suave: velocidad y aceleración suaves por cada clave.\n- Catmull-Rom: mover una clave solo afecta la ruta cercana.\n- Rectas: giran en cada clave."),
    PT("- Spline suave: velocidade e aceleração suaves em cada chave.\n- Catmull-Rom: mover uma chave afeta só o caminho próximo.\n- Retas: viram em cada chave."),
    IT("- Spline fluida: velocità e accelerazione continue in ogni chiave.\n- Catmull-Rom: spostare una chiave cambia solo il percorso vicino.\n- Rette: svolta a ogni chiave."),
    NL("- Gladde spline: vloeiende snelheid en versnelling door elke keyframe.\n- Catmull-Rom: keyframe verplaatsen beïnvloedt alleen nabijgelegen paden.\n- Rechte lijnen: draai bij elke keyframe."),
    RU("- Плавный сплайн: скорость и ускорение плавно меняются через все ключи.\n- Catmull-Rom: сдвиг ключа меняет лишь соседние участки пути.\n- Прямые: поворот у каждого ключа."),
    TR("- Yumuşak eğri: hız ve ivme her anahtardan yumuşak geçer.\n- Catmull-Rom: anahtar taşımak yalnız yakın yolu etkiler.\n- Düz çizgi: her anahtarda döner."));

