SS_MSG(motion_loop_help,
    EN("After the last keyframe the camera goes back to the first, so the video ends where it began and plays round and round without a jump."),
    JA("最後のキーフレームの後、カメラは最初へ戻ります。動画は始まりと同じ所で終わり、継ぎ目なく繰り返し再生できます。"),
    ZH_HANS("最后一个关键帧之后相机回到第一个，视频在开始的地方结束，可以无跳变地循环播放。"),
    ZH_HANT("最後一個關鍵影格之後相機回到第一個，影片在開始的地方結束，可以無跳變地循環播放。"),
    KO("마지막 키프레임 뒤에 카메라가 처음으로 돌아가, 동영상이 시작한 곳에서 끝나고 끊김 없이 반복 재생됩니다."),
    DE("Nach dem letzten Keyframe fährt die Kamera zurück zum ersten; das Video endet, wo es begann, und läuft ohne Sprung immer wieder."),
    FR("Après la dernière image clé, la caméra revient à la première : la vidéo finit où elle a commencé et tourne en boucle sans saut."),
    ES("Tras el último fotograma clave la cámara vuelve al primero: el vídeo termina donde empezó y se repite sin saltos."),
    PT("Depois do último quadro-chave a câmera volta ao primeiro: o vídeo termina onde começou e se repete sem salto."),
    IT("Dopo l'ultimo fotogramma chiave la camera torna al primo: il video finisce dove è iniziato e si ripete senza salti."),
    NL("Na de laatste keyframe gaat de camera terug naar de eerste: de video eindigt waar hij begon en speelt zonder sprong rond."),
    RU("После последнего ключевого кадра камера возвращается к первому: видео кончается там, где началось, и крутится по кругу без скачка."),
    TR("Son anahtar kareden sonra kamera ilkine döner; video başladığı yerde biter ve sıçramadan tekrar tekrar oynar."));

