SS_MSG(motion_constant_help,
    EN("The same speed all along the path, whatever the keyframes' times: a cluster of keyframes close together no longer crawls."),
    JA("キーフレームの時刻にかかわらず、経路全体を同じ速さで進みます。キーフレームが密集した所でも遅くなりません。"),
    ZH_HANS("无论关键帧的时间如何，整条路径速度都相同：关键帧挤在一起的地方不再慢吞吞。"),
    ZH_HANT("無論關鍵影格的時間如何，整條路徑速度都相同：關鍵影格擠在一起的地方不再慢吞吞。"),
    KO("키프레임의 시간과 상관없이 경로 전체를 같은 속도로 갑니다. 키프레임이 몰린 곳에서도 느려지지 않습니다."),
    DE("Überall auf dem Weg dasselbe Tempo, egal wie die Keyframes zeitlich liegen: Eine Gruppe dicht beieinander liegender Keyframes kriecht nicht mehr."),
    FR("La même vitesse sur tout le trajet, quels que soient les temps des images clés : un groupe d'images clés rapprochées ne se traîne plus."),
    ES("La misma velocidad en todo el recorrido, sean cuales sean los tiempos de los fotogramas clave: un grupo de fotogramas clave muy juntos ya no se arrastra."),
    PT("A mesma velocidade em todo o percurso, quaisquer que sejam os tempos dos quadros-chave: um grupo de quadros-chave próximos já não se arrasta."),
    IT("La stessa velocità lungo tutto il percorso, qualunque siano i tempi dei fotogrammi chiave: un gruppo di fotogrammi chiave vicini non striscia più."),
    NL("Overal op het pad dezelfde snelheid, wat de tijden van de keyframes ook zijn: een groepje keyframes dicht bij elkaar kruipt niet meer."),
    RU("Одна скорость на всём пути, каким бы ни было время ключевых кадров: там, где они стоят тесно, камера больше не ползёт."),
    TR("Anahtar karelerin zamanları ne olursa olsun yol boyunca aynı hız: birbirine yakın anahtar kare kümeleri artık sürünmez."));

