SS_MSG(motion_tension_help,
    EN("0 is a loose curve through the keyframes; 1 slows to a stop at every one."),
    JA("0 はキーフレームを通るゆるい曲線、1 は各キーフレームで一度止まります。"),
    ZH_HANS("0 是穿过关键帧的松弛曲线；1 在每个关键帧处都减速停下。"),
    ZH_HANT("0 是穿過關鍵影格的鬆弛曲線；1 在每個關鍵影格處都減速停下。"),
    KO("0은 키프레임을 지나는 느슨한 곡선이고, 1은 키프레임마다 멈춥니다."),
    DE("0 ist eine lockere Kurve durch die Keyframes; 1 bremst an jedem bis zum Stillstand."),
    FR("0 est une courbe souple à travers les images clés ; 1 ralentit jusqu'à l'arrêt à chacune."),
    ES("0 es una curva suelta que pasa por los fotogramas clave; 1 frena hasta parar en cada uno."),
    PT("0 é uma curva solta pelos quadros-chave; 1 desacelera até parar em cada um."),
    IT("0 è una curva morbida attraverso i fotogrammi chiave; 1 rallenta fino a fermarsi a ciascuno."),
    NL("0 is een losse bocht door de keyframes; 1 remt bij elke af tot stilstand."),
    RU("0 — свободная кривая через ключевые кадры; 1 — остановка на каждом."),
    TR("0 anahtar karelerden geçen gevşek bir eğridir; 1 her birinde durana kadar yavaşlar."));

