SS_MSG(smooth_keys_help,
    EN("Smooth keyframe poses, timing or both.\n- Pose smoothing softens path bends. Timing smoothing evens gaps along the path.\n- Applies to the selection or all keys. Keeps the first, last and stops fixed.\n- Press again for more smoothing."),
    JA("各キーフレームを、隣のキーフレームが示す位置へ少し近づけます。姿勢なら経路のねじれが取れ、時刻ならキーフレームの間隔がそろい、両方も選べます。\n- 選択したキーフレームに、何も選択していなければすべてに働きます。最初と最後と停止点は動きません。\n- もう一度押すとさらになめらかになります。"),
    ZH_HANS("让每个关键帧朝相邻关键帧所指的位置移动一部分：可以是姿态，消除路径上的扭折；可以是时间，让关键帧间隔均匀；也可以两者都做。\n作用于选中的关键帧，未选中时作用于全部；第一个、最后一个和停留点保持不动。再按一次会更平滑。"),
    ZH_HANT("讓每個關鍵影格朝相鄰關鍵影格所指的位置移動一部分：可以是姿態，消除路徑上的扭折；可以是時間，讓關鍵影格間隔均勻；也可以兩者都做。\n作用於選取的關鍵影格，未選取時作用於全部；第一個、最後一個和停留點保持不動。再按一次會更平滑。"),
    KO("각 키프레임을 이웃 키프레임이 가리키는 곳으로 조금씩 옮깁니다. 자세를 옮기면 경로의 꺾임이 펴지고, 시간을 옮기면 키프레임 간격이 고르게 되며, 둘 다 할 수도 있습니다.\n- 선택한 키프레임에, 선택이 없으면 전부에 작동하며 처음, 마지막, 멈춤 지점은 그대로입니다.\n- 다시 누르면 더 매끄러워집니다."),
    DE("Keyframe-Posen, Timing oder beides glätten.\n- Posen glätten Kurven, Timing gleicht Abstände aus.\n- Auswahl oder alle Keys. Erster, letzter und Halte bleiben fest.\n- Erneut drücken, um weiter zu glätten."),
    FR("Rapproche chaque image clé de l'endroit où ses voisines la placeraient :\n- sa pose, pour ôter les coudes du trajet, son temps, pour égaliser les écarts entre images clés, ou les deux.\n- Agit sur les images clés choisies, ou sur toutes si aucune ne l'est ;\n- la première, la dernière et les arrêts ne bougent pas. Appuyez encore pour lisser davantage."),
    ES("Acerca cada fotograma clave a donde lo pondrían sus vecinos: su pose, quitando quiebros al recorrido, su tiempo, igualando los huecos entre fotogramas clave, o ambos.\n- Actúa sobre los fotogramas clave elegidos, o sobre todos si no hay ninguno elegido;\n- el primero, el último y las paradas se quedan donde están. Pulse otra vez para suavizar más."),
    PT("Aproxima cada quadro-chave de onde os vizinhos o poriam: a pose, tirando dobras do percurso, o tempo, igualando os intervalos entre quadros-chave, ou ambos.\n- Age nos quadros-chave escolhidos, ou em todos quando nenhum está escolhido;\n- o primeiro, o último e as paradas ficam onde estão. Pressione de novo para suavizar mais."),
    IT("Smussa pose, tempi o entrambi.\n- Le pose addolciscono le curve, i tempi uniformano gli intervalli.\n- Agisce sulla selezione o su tutte le chiavi. Primo, ultimo e soste restano fissi.\n- Premi ancora per smussare di più."),
    NL("Verplaatst elke keyframe een stuk naar waar zijn buren hem zouden zetten:\n- zijn stand, wat knikken uit het pad haalt, zijn tijd, wat de gaten tussen keyframes gelijkmatiger maakt, of beide.\n- Werkt op de gekozen keyframes, of op allemaal als er geen gekozen is;\n- de eerste, de laatste en de stops blijven staan. Druk opnieuw om verder te gladden."),
    RU("Сдвигает каждый ключевой кадр туда, куда поставили бы его соседи: положение — убирая изломы пути, время — выравнивая промежутки между кадрами, или то и другое.\n- Действует на выбранные ключевые кадры или на все, если ничего не выбрано;\n- первый, последний и остановки остаются на месте. Нажмите ещё раз, чтобы сгладить сильнее."),
    TR("Her anahtar kareyi komşularının koyacağı yere biraz yaklaştırır: duruşunu, yoldaki kırıkları gidererek;\n- zamanını, anahtar kareler arasındaki boşlukları eşitleyerek; ya da ikisini.\n- Seçili anahtar karelere, hiçbiri seçili değilse hepsine etki eder; ilk, son ve duraklar yerinde kalır.\n- Daha fazla yumuşatmak için yeniden basın."));

