SS_MSG(smooth_what_help,
    EN("- What may change. Poses: where the cameras are and look, each at its own time.\n- Timing: when each keyframe is passed, along the same path, so the camera speeds up and slows down gradually.\n- Both: all of it. A press is kept only when the motion comes out smoother."),
    JA("- 何を変えてよいかです。 姿勢: カメラの位置と向き。 各キーフレームの時刻はそのまま。\n- タイミング: 同じ経路のまま各キーフレームを通る時刻を変え、カメラが徐々に速くなったり遅くなったりするようにします。\n- 両方: そのすべて。 動きがなめらかになったときだけ結果を残します。"),
    ZH_HANS("- 允许改变什么。 姿态：相机的位置和朝向，各自的时间不变。\n- 时间：沿同一条路径改变经过每个关键帧的时刻，让相机平缓地加速和减速。 两者：全部都可以改。\n- 只有运动变得更平滑时才保留结果。"),
    ZH_HANT("- 允許改變什麼。 姿態：相機的位置和朝向，各自的時間不變。\n- 時間：沿同一條路徑改變經過每個關鍵影格的時刻，讓相機平緩地加速和減速。 兩者：全部都可以改。\n- 只有運動變得更平滑時才保留結果。"),
    KO("- 무엇을 바꿔도 되는지입니다. 자세: 카메라의 위치와 바라보는 곳, 각자의 시간은 그대로.\n- 타이밍: 같은 경로에서 각 키프레임을 지나는 때를 바꿔 카메라가 서서히 빨라지고 느려지게 합니다. 둘 다: 전부.\n- 움직임이 더 매끄러워질 때만 결과를 남깁니다."),
    DE("- Lagen: Kameraposition und Blick ändern, Zeiten beibehalten. Zeiten: Tempo auf gleichem Weg glätten.\n- Beides: Lagen und Zeiten. Änderungen bleiben nur, wenn die Bewegung glatter wird."),
    FR("- Poses : change position et regard, pas les temps. Temps : lisse la vitesse sur le même trajet.\n- Les deux : poses et temps. Changements gardés seulement si le mouvement devient plus fluide."),
    ES("- Qué puede cambiar. Poses: dónde están las cámaras y adónde miran, cada una en su tiempo.\n- Tiempos: cuándo se pasa cada fotograma clave, por el mismo recorrido, para que la cámara acelere y frene poco a poco.\n- Ambos: todo ello. Una pulsación solo se conserva si el movimiento sale más suave."),
    PT("- O que pode mudar. Poses: onde as câmeras estão e para onde olham, cada uma no seu tempo.\n- Tempos: quando cada quadro-chave é passado, no mesmo percurso, para a câmera acelerar e frear aos poucos.\n- Ambos: tudo isso. Um clique só é mantido se o movimento ficar mais suave."),
    IT("- Pose: cambia posizione e sguardo, non i tempi. Tempi: rende fluida la velocità sullo stesso percorso.\n- Entrambi: pose e tempi. Modifiche mantenute solo se il movimento migliora."),
    NL("- Standen: positie en kijkrichting wijzigen, tijden behouden. Tijden: snelheid op hetzelfde pad gladden.\n- Beide: standen en tijden. Wijzigingen blijven alleen als de beweging vloeiender wordt."),
    RU("- Что можно менять. Положения: где камеры и куда они смотрят, каждая в своё время.\n- Время: когда проходится каждый ключевой кадр, по тому же пути, чтобы камера ускорялась и замедлялась постепенно.\n- И то, и другое: всё это. Нажатие остаётся, только если движение стало плавнее."),
    TR("- Neyin değişebileceği. Duruşlar: kameraların nerede olduğu ve nereye baktığı, her biri kendi zamanında.\n- Zamanlama: aynı yolda her anahtar kareden ne zaman geçildiği; kamera yavaş yavaş hızlanıp yavaşlar.\n- İkisi: hepsi. Bir basış yalnızca hareket daha akıcı olursa kalır."));

SS_MSG(smooth_speed_off,
    EN("Constant speed is off: the keyframes are now passed at their smoothed times."),
    JA("一定速度をオフにしました。キーフレームはなめらかにした時刻に通ります。"),
    ZH_HANS("已关闭匀速：关键帧现在按平滑后的时间经过。"),
    ZH_HANT("已關閉等速：關鍵影格現在按平滑後的時間經過。"),
    KO("일정한 속도를 껐습니다. 이제 키프레임을 매끄럽게 한 시간에 지납니다."),
    DE("Konstante Geschwindigkeit ist aus: Die Keyframes werden jetzt zu ihren geglätteten Zeiten durchlaufen."),
    FR("La vitesse constante est désactivée : les images clés sont maintenant passées à leurs temps lissés."),
    ES("La velocidad constante está desactivada: los fotogramas clave se pasan ahora en sus tiempos suavizados."),
    PT("A velocidade constante está desligada: os quadros-chave agora são passados nos tempos suavizados."),
    IT("La velocità costante è disattivata: i fotogrammi chiave ora si passano ai loro tempi ammorbiditi."),
    NL("Constante snelheid staat uit: de keyframes worden nu op hun gladgestreken tijden gepasseerd."),
    RU("Постоянная скорость выключена: ключевые кадры теперь проходятся в сглаженные моменты."),
    TR("Sabit hız kapalı: anahtar karelerden artık yumuşatılmış zamanlarında geçiliyor."));

