SS_MSG(up_from_view,
    EN("Take up from the view"),
    JA("ビューから上方向を取る"),
    ZH_HANS("从视图取上方向"),
    ZH_HANT("從視圖取上方向"),
    KO("뷰에서 위쪽 가져오기"),
    DE("Oben aus der Ansicht übernehmen"),
    FR("Prendre le haut depuis la vue"),
    ES("Tomar el arriba de la vista"),
    PT("Pegar o “para cima” da vista"),
    IT("Prendi l'alto dalla vista"),
    NL("Boven uit het beeld nemen"),
    RU("Взять верх из вида"),
    TR("Yukarıyı görünümden al"));

SS_MSG(up_from_view_help,
    EN("Which way is up decides how an orbit turns and how an aimed camera stays level. Turn the view until the horizon is level, then press this."),
    JA("どちらが上かで、周回の回り方と、注視するカメラの水平の保ち方が決まります。地平線が水平になるまでビューを回してから押してください。"),
    ZH_HANS("哪边是上决定了环绕怎么转、注视的相机怎样保持水平。把视图转到地平线水平，再按这里。"),
    ZH_HANT("哪邊是上決定了環繞怎麼轉、注視的相機怎樣保持水平。把視圖轉到地平線水平，再按這裡。"),
    KO("어느 쪽이 위인지에 따라 돌기가 도는 방식과 한 점을 보는 카메라가 수평을 유지하는 방식이 정해집니다. 지평선이 수평이 되도록 뷰를 돌린 뒤 누르세요."),
    DE("Wo oben ist, bestimmt, wie eine Umkreisung dreht und wie eine zielende Kamera waagerecht bleibt. Die Ansicht drehen, bis der Horizont waagerecht ist, dann hier drücken."),
    FR("Le haut décide comment une orbite tourne et comment une caméra qui vise reste de niveau. Tournez la vue jusqu'à ce que l'horizon soit droit, puis appuyez ici."),
    ES("Hacia dónde está arriba decide cómo gira una órbita y cómo una cámara que apunta se mantiene nivelada. Gire la vista hasta que el horizonte esté recto y pulse aquí."),
    PT("Para onde fica o alto decide como uma órbita gira e como uma câmera que mira fica nivelada. Gire a vista até o horizonte ficar reto e clique aqui."),
    IT("Dove sta l'alto decide come gira un'orbita e come una camera che mira resta in bolla. Ruota la vista finché l'orizzonte è dritto, poi premi qui."),
    NL("Waar boven is, bepaalt hoe een rondgang draait en hoe een richtende camera waterpas blijft. Draai het beeld tot de horizon recht is en druk dan hierop."),
    RU("От того, где верх, зависит, как идёт облёт и как нацеленная камера держит горизонт. Поверните вид, пока горизонт не станет ровным, и нажмите сюда."),
    TR("Yukarının neresi olduğu, bir turun nasıl döneceğini ve hedefe bakan bir kameranın nasıl düz kalacağını belirler. Ufuk düzelene kadar görünümü çevirin, sonra buna basın."));

SS_MSG(up_unknown,
    EN("Nothing says which way is up in this model. If the view is not upright, turn it until it is, then take up from it."),
    JA("このモデルにはどちらが上かの情報がありません。ビューがまっすぐでなければ、まっすぐになるまで回してから上方向を取ってください。"),
    ZH_HANS("此模型没有说明哪边是上。如果视图不是正的，就把它转正，再从中取上方向。"),
    ZH_HANT("此模型沒有說明哪邊是上。如果視圖不是正的，就把它轉正，再從中取上方向。"),
    KO("이 모델에는 어느 쪽이 위인지 알려 주는 것이 없습니다. 뷰가 바로 서 있지 않다면 바로 설 때까지 돌린 뒤 위쪽을 가져오세요."),
    DE("Nichts in diesem Modell sagt, wo oben ist. Steht die Ansicht nicht aufrecht, sie so drehen, bis sie es tut, und dann oben daraus übernehmen."),
    FR("Rien dans ce modèle n'indique où est le haut. Si la vue n'est pas droite, tournez-la jusqu'à ce qu'elle le soit, puis prenez-en le haut."),
    ES("Nada en este modelo indica dónde está arriba. Si la vista no está derecha, gírela hasta que lo esté y tome de ella el arriba."),
    PT("Nada neste modelo diz onde fica o alto. Se a vista não estiver em pé, gire-a até ficar e pegue dela o “para cima”."),
    IT("Niente in questo modello dice dov'è l'alto. Se la vista non è dritta, ruotala finché lo è, poi prendi l'alto da lei."),
    NL("Niets in dit model zegt waar boven is. Staat het beeld niet rechtop, draai het dan tot het dat wel doet en neem boven eruit."),
    RU("В этой модели ничто не говорит, где верх. Если вид стоит не прямо, поверните его, а затем возьмите верх из него."),
    TR("Bu modelde yukarının neresi olduğunu söyleyen bir şey yok. Görünüm dik değilse dik olana kadar çevirin, sonra yukarıyı ondan alın."));


