SS_MSG(model_remove_help,
    EN("Close this model. Shots that showed it show the first model instead; closing the first one makes the next one first."),
    JA("このモデルを閉じます。このモデルを見せていたショットは最初のモデルを見せます。最初のモデルを閉じると、次のモデルが最初になります。"),
    ZH_HANS("关闭此模型。原本显示它的镜头改为显示第一个模型；关闭第一个时，下一个成为第一个。"),
    ZH_HANT("關閉此模型。原本顯示它的鏡頭改為顯示第一個模型；關閉第一個時，下一個成為第一個。"),
    KO("이 모델을 닫습니다. 이 모델을 보여 주던 샷은 첫 번째 모델을 보여 주고, 첫 번째를 닫으면 다음 모델이 첫 번째가 됩니다."),
    DE("Dieses Modell schließen. Einstellungen, die es zeigten, zeigen stattdessen das erste Modell; wird das erste geschlossen, wird das nächste zum ersten."),
    FR("Fermer ce modèle. Les plans qui le montraient montrent le premier modèle à la place ; fermer le premier fait du suivant le premier."),
    ES("Cerrar este modelo. Las tomas que lo mostraban muestran el primer modelo en su lugar; al cerrar el primero, el siguiente pasa a ser el primero."),
    PT("Fechar este modelo. As tomadas que o mostravam passam a mostrar o primeiro modelo; fechar o primeiro faz do seguinte o primeiro."),
    IT("Chiudi questo modello. Le inquadrature che lo mostravano mostrano invece il primo modello; chiudendo il primo, il successivo diventa il primo."),
    NL("Dit model sluiten. Shots die het toonden, tonen in plaats daarvan het eerste model; sluit je het eerste, dan wordt het volgende het eerste."),
    RU("Закрыть эту модель. Планы, где она была, покажут первую модель; если закрыть первую, первой станет следующая."),
    TR("Bu modeli kapat. Onu gösteren çekimler bunun yerine ilk modeli gösterir; ilki kapatılırsa sıradaki ilk olur."));

