SS_MSG(model_primitive_help,
    EN("Choose the splat type used for rendering.\n- Auto uses 3DGUT for 360° and folding distortions where 3DGS smears.\n- Otherwise uses the trained Mip or 3DGS type."),
    JA("モデルをどの種類のガウシアンとして描くかです。\n自動では、3DGSがにじむ所 -- 360度レンズや、画面のどこかで折り返すほどの歪み -- で3DGUTを使い、それ以外では学習したときの種類（Mip、それ以外は3DGS）を使います。"),
    ZH_HANS("把模型渲染成哪种高斯。\n自动：在 3DGS 会糊掉的地方——360° 镜头，或画面中某处畸变折叠——用 3DGUT，其他地方用模型训练时的方式，Mip 或 3DGS。"),
    ZH_HANT("把模型算繪成哪種高斯。\n自動：在 3DGS 會糊掉的地方——360° 鏡頭，或畫面中某處畸變折疊——用 3DGUT，其他地方用模型訓練時的方式，Mip 或 3DGS。"),
    KO("모델을 어떤 가우시안으로 렌더링할지입니다.\n자동은 3DGS가 번지는 곳 -- 360° 렌즈, 또는 화면 어딘가에서 접히는 왜곡 -- 에서 3DGUT를, 나머지에서는 모델이 학습된 방식인 Mip이나 3DGS를 씁니다."),
    DE("Als welche Art Splat das Modell gerendert wird.\nAutomatisch nimmt 3DGUT, wo 3DGS verschmieren würde – bei einem 360°-Objektiv oder einer Verzeichnung, die sich irgendwo im Bild überschlägt –, und sonst das, womit das Modell trainiert wurde, Mip oder 3DGS."),
    FR("Le type de splat avec lequel rendre le modèle.\nAutomatique utilise 3DGUT là où 3DGS baverait – un objectif à 360°, ou une distorsion qui se replie quelque part dans l'image – et ailleurs ce avec quoi le modèle a été entraîné, Mip ou 3DGS."),
    ES("Con qué tipo de splat renderizar el modelo.\nAutomático usa 3DGUT donde 3DGS se emborronaría –un objetivo de 360°, o una distorsión que se repliega en algún punto de la imagen– y en lo demás aquello con lo que se entrenó el modelo, Mip o 3DGS."),
    PT("Com que tipo de splat renderizar o modelo.\nAutomático usa 3DGUT onde o 3DGS borraria – uma lente de 360°, ou uma distorção que se dobra em algum ponto da imagem – e no resto aquilo com que o modelo foi treinado, Mip ou 3DGS."),
    IT("Con quale tipo di splat renderizzare il modello.\nAutomatico usa 3DGUT dove 3DGS sbaverebbe – un obiettivo a 360°, o una distorsione che si ripiega da qualche parte nell'immagine – e altrove ciò con cui il modello è stato addestrato, Mip o 3DGS."),
    NL("Als welk soort splat het model wordt gerenderd.\nAutomatisch gebruikt 3DGUT waar 3DGS zou uitsmeren – een 360°-lens, of een vervorming die ergens in beeld over zichzelf heen vouwt – en elders waarmee het model is getraind, Mip of 3DGS."),
    RU("Каким видом сплатов рендерить модель.\n«Автоматически» берёт 3DGUT там, где 3DGS размазывает, — объектив на 360° или дисторсия, которая где-то в кадре заворачивается, — а в остальном то, на чём модель обучена, Mip или 3DGS."),
    TR("Modelin hangi tür splat olarak işleneceği. Otomatik, 3DGS'nin bulaşacağı yerde – 360° bir lens ya da görüntünün bir yerinde üstüne katlanan bir bozulma – 3DGUT'u, başka yerlerde modelin eğitildiği yöntemi, Mip ya da 3DGS'yi kullanır."));

