SS_MSG(shot_move_help,
    EN("Earlier or later: the shot trades its model, its transition and its way out with the one next to it; the times stay."),
    JA("前へ・後ろへ: ショットのモデル、トランジション、退場を隣のショットと入れ替えます。時刻はそのままです。"),
    ZH_HANS("提前或延后：此镜头与相邻镜头交换模型、转场和离场，时间不变。"),
    ZH_HANT("提前或延後：此鏡頭與相鄰鏡頭交換模型、轉場和離場，時間不變。"),
    KO("앞으로 또는 뒤로: 샷이 이웃한 샷과 모델, 전환, 퇴장을 맞바꿉니다. 시간은 그대로입니다."),
    DE("Früher oder später: Die Einstellung tauscht Modell, Übergang und Abgang mit der benachbarten; die Zeiten bleiben."),
    FR("Plus tôt ou plus tard : le plan échange son modèle, sa transition et sa sortie avec son voisin ; les temps restent."),
    ES("Antes o después: la toma intercambia su modelo, su transición y su salida con la de al lado; los tiempos se quedan."),
    PT("Antes ou depois: a tomada troca modelo, transição e saída com a vizinha; os tempos ficam."),
    IT("Prima o dopo: l'inquadratura scambia modello, transizione e uscita con quella accanto; i tempi restano."),
    NL("Eerder of later: de shot ruilt model, overgang en vertrek met de naburige; de tijden blijven."),
    RU("Раньше или позже: план меняется моделью, переходом и уходом с соседним; время остаётся."),
    TR("Daha önce ya da sonra: çekim, modelini, geçişini ve çıkışını yanındakiyle değiştirir; zamanlar aynı kalır."));

