SS_MSG(shot_exit_help,
    EN("- As next arrives: use the next shot’s transition for both models.\n- Other choices exit independently with their own timing, allowing overlap or a gap."),
    JA("- 次の到着時：次のショットのトランジションを両モデルに使います。\n- 他の選択肢：独自の時間で退場し、重なりや空白を作れます。"),
    ZH_HANS("- 下一镜头到来时：两个模型都使用下一镜头的过渡。\n- 其他选项独立退场，可设置自己的时间，允许重叠或空隙。"),
    ZH_HANT("- 下一鏡頭到來時：兩個模型都使用下一鏡頭的轉場。\n- 其他選項獨立退場，可設定自己的時間，允許重疊或空隙。"),
    KO("- 다음 도착 시: 두 모델 모두 다음 샷의 전환을 씁니다.\n- 다른 선택은 독립된 시간으로 퇴장해 겹침이나 빈 구간을 만들 수 있습니다."),
    DE("- Wenn der nächste ankommt: Übergang des nächsten Shots für beide Modelle nutzen.\n- Andere Optionen verlassen mit eigenem Timing; Überlappung oder Lücke ist möglich."),
    FR("- À l’arrivée suivante : utilise la transition du plan suivant pour les deux modèles.\n- Autres choix : sortie indépendante, permettant chevauchement ou vide."),
    ES("- Al llegar el siguiente: usa la transición del siguiente plano para ambos modelos.\n- Otras opciones salen con tiempo propio, permitiendo solapamiento o hueco."),
    PT("- Ao chegar o próximo: usa a transição do próximo plano para ambos os modelos.\n- Outras opções saem com tempo próprio, permitindo sobreposição ou intervalo."),
    IT("- All’arrivo successivo: usa la transizione della prossima inquadratura per entrambi.\n- Altre opzioni escono con tempi propri, permettendo sovrapposizione o vuoto."),
    NL("- Als de volgende aankomt: gebruik diens overgang voor beide modellen.\n- Andere keuzes vertrekken met eigen timing, met overlap of een lege tussenruimte."),
    RU("- При появлении следующего: переход следующего кадра для обеих моделей.\n- Другие варианты уходят по своему времени, оставляя перекрытие или пустой промежуток."),
    TR("- Sonraki geldiğinde: iki model de sonraki çekimin geçişini kullanır.\n- Diğer seçenekler kendi süresinde çıkar; örtüşme veya boşluk bırakabilir."));

