SS_MSG(shot_exit_offset_help,
    EN("When it starts to leave, in seconds from the start of the next shot: below 0 it goes before the next one comes, above 0 both are on screen for a while."),
    JA("去り始める時刻を、次のショットの開始からの秒数で表します。\n0 より小さいと次が来る前に去り、0 より大きいとしばらく両方が映ります。"),
    ZH_HANS("它开始离开的时刻，以距下一个镜头开始的秒数计：小于 0 时在下一个到来之前离开，大于 0 时两者会同屏一段时间。"),
    ZH_HANT("它開始離開的時刻，以距下一個鏡頭開始的秒數計：小於 0 時在下一個到來之前離開，大於 0 時兩者會同框一段時間。"),
    KO("떠나기 시작하는 때를 다음 샷 시작부터의 초로 나타냅니다. 0보다 작으면 다음 샷이 오기 전에 떠나고, 0보다 크면 한동안 둘 다 화면에 있습니다."),
    DE("Wann es zu gehen beginnt, in Sekunden ab dem Beginn der nächsten Einstellung: unter 0 geht es, bevor die nächste kommt, über 0 sind eine Weile beide im Bild."),
    FR("Quand il commence à partir, en secondes depuis le début du plan suivant : sous 0 il part avant que le suivant n'arrive, au-dessus de 0 les deux sont à l'écran un moment."),
    ES("Cuándo empieza a irse, en segundos desde el comienzo de la toma siguiente: por debajo de 0 se va antes de que llegue la siguiente, por encima de 0 ambas están en pantalla un rato."),
    PT("Quando começa a sair, em segundos a partir do início da tomada seguinte: abaixo de 0 sai antes de a próxima chegar, acima de 0 as duas ficam na tela por um tempo."),
    IT("Inizio uscita, in secondi dall’inizio della prossima inquadratura. Sotto 0 esce prima; sopra 0 i due modelli restano sovrapposti."),
    NL("Wanneer het begint te vertrekken, in seconden vanaf het begin van de volgende shot: onder 0 gaat het voordat de volgende komt, boven 0 zijn ze een tijdje allebei in beeld."),
    RU("Когда начинается уход, в секундах от начала следующего плана: меньше 0 — уходит до прихода следующего, больше 0 — какое-то время в кадре обе."),
    TR("Gitmeye ne zaman başladığı, sonraki çekimin başından itibaren saniye olarak: 0'dan küçükse sonraki gelmeden gider, 0'dan büyükse bir süre ikisi de ekranda olur."));

SS_MSG(shot_exit_stays,
    EN("stays to the end"),
    JA("最後まで残る"),
    ZH_HANS("一直留到最后"),
    ZH_HANT("一直留到最後"),
    KO("끝까지 남기"),
    DE("bleibt bis zum Ende"),
    FR("reste jusqu'à la fin"),
    ES("se queda hasta el final"),
    PT("fica até o fim"),
    IT("resta fino alla fine"),
    NL("blijft tot het einde"),
    RU("остаётся до конца"),
    TR("sonuna kadar kalır"));

SS_MSG(shot_exit_last_help,
    EN("How the last shot's model goes at the end of the video. A dip fades it into the colour and holds it there;\nany other transition takes it out over its own time. Stays to the end keeps it until the last frame."),
    JA("最後のショットのモデルが動画の終わりにどう去るかです。 色を挟むとその色へフェードし、そのまま保ちます。\nほかのトランジションは独自の時間で退場させます。 「最後まで残る」は最後のフレームまで残します。"),
    ZH_HANS("最后一个镜头的模型在视频结尾如何离开。 经由颜色会淡入那个颜色并停在那里； 其他转场会用它自己的时长把模型带走。\n“一直留到最后”让它留到最后一帧。"),
    ZH_HANT("最後一個鏡頭的模型在影片結尾如何離開。 經由顏色會淡入那個顏色並停在那裡； 其他轉場會用它自己的時長把模型帶走。\n「一直留到最後」讓它留到最後一格。"),
    KO("마지막 샷의 모델이 영상 끝에서 떠나는 방식입니다.\n- 색 전환은 그 색으로 페이드되어 그대로 머물고, 다른 전환은 자기 시간 동안 모델을 데려갑니다.\n- '끝까지 남기'는 마지막 프레임까지 남깁니다."),
    DE("Wie das Modell der letzten Einstellung am Ende des Videos geht. Farbe blendet es in die Farbe und hält sie;\njeder andere Übergang nimmt es in eigener Dauer mit. „Bleibt bis zum Ende“ behält es bis zum letzten Bild."),
    FR("Comment le modèle du dernier plan s'en va à la fin de la vidéo. Couleur le fond dans la couleur et l'y maintient ;\ntoute autre transition l'emporte sur sa propre durée. « Reste jusqu'à la fin » le garde jusqu'à la dernière image."),
    ES("Cómo se va el modelo de la última toma al final del vídeo. Color lo funde en ese color y lo mantiene;\n- cualquier otra transición se lo lleva en su propia duración.\n- «Se queda hasta el final» lo mantiene hasta el último fotograma."),
    PT("Como o modelo da última tomada sai no fim do vídeo. Cor o funde nessa cor e a mantém;\nqualquer outra transição o leva em sua própria duração. «Fica até o fim» o mantém até o último quadro."),
    IT("Come se ne va il modello dell'ultima inquadratura alla fine del video.\n- Colore lo dissolve in quel colore e lo tiene; qualsiasi altra transizione lo porta via nella sua durata.\n- «Resta fino alla fine» lo tiene fino all'ultimo fotogramma."),
    NL("Hoe het model van de laatste shot aan het einde van de video vertrekt.\n- Kleur laat het overvloeien in die kleur en houdt die vast; elke andere overgang neemt het mee in een eigen duur.\n- ‘Blijft tot het einde’ houdt het tot het laatste beeld."),
    RU("Как уходит модель последнего плана в конце видео. Цвет растворяет её в этом цвете и держит его;\nлюбой другой переход уводит её за своё время. «Остаётся до конца» держит её до последнего кадра."),
    TR("Son çekimin modelinin videonun sonunda nasıl gittiği. Renk onu o renge karartır ve orada tutar;\nbaşka her geçiş onu kendi süresiyle götürür. «Sonuna kadar kalır» onu son kareye kadar tutar."));

SS_MSG(shot_exit_offset_last_help,
    EN("When it has finished leaving, in seconds from the end of the video: below 0 it is gone before the end, and the rest is the background, or the colour of a dip."),
    JA("去り終える時刻を、動画の終わりからの秒数で表します。0 より小さいと終わる前に消え、残りは背景か、色を挟んだならその色になります。"),
    ZH_HANS("它离开完毕的时刻，以距视频结尾的秒数计：小于 0 时在结尾前消失，剩下的是背景，或经由颜色时的那个颜色。"),
    ZH_HANT("它離開完畢的時刻，以距影片結尾的秒數計：小於 0 時在結尾前消失，剩下的是背景，或經由顏色時的那個顏色。"),
    KO("떠나기를 마치는 때를 영상 끝부터의 초로 나타냅니다. 0보다 작으면 끝나기 전에 사라지고, 나머지는 배경이나 색 전환의 색이 됩니다."),
    DE("Wann es fertig gegangen ist, in Sekunden ab dem Ende des Videos: unter 0 ist es vor dem Ende weg, und der Rest ist der Hintergrund oder die Farbe."),
    FR("Quand il a fini de partir, en secondes depuis la fin de la vidéo : sous 0 il a disparu avant la fin, et le reste est le fond, ou la couleur."),
    ES("Cuándo ha terminado de irse, en segundos desde el final del vídeo: por debajo de 0 desaparece antes del final, y el resto es el fondo, o el color."),
    PT("Quando termina de sair, em segundos a partir do fim do vídeo: abaixo de 0 some antes do fim, e o resto é o fundo, ou a cor."),
    IT("Quando ha finito di andarsene, in secondi dalla fine del video: sotto 0 sparisce prima della fine, e il resto è lo sfondo, o il colore."),
    NL("Wanneer het klaar is met vertrekken, in seconden vanaf het einde van de video: onder 0 is het voor het einde weg, en de rest is de achtergrond, of de kleur."),
    RU("Когда уход заканчивается, в секундах от конца видео: меньше 0 — исчезает до конца, а остальное — фон или цвет."),
    TR("Gitmeyi ne zaman bitirdiği, videonun sonundan itibaren saniye olarak: 0'dan küçükse sondan önce kaybolur, geri kalanı arka plan ya da renk olur."));

