SS_MSG(tr_help,
    EN("Choose how shots transition.\n- Image: crossfade, dip, wipe, iris or zoom.\n- 3D reveal: sweep along up, spiral in, rain down or ripple from center.\n- 3D removal or swap: dust crumbles the old model, scatter breaks and gathers, dissolve swaps grains."),
    JA("クロスフェード、色を挟む、ワイプ、アイリス、ズームは画面上で働きます。残りはモデルそのものを3Dで動かします。\nスイープは上方向に沿って現し、塵は古いモデルを崩し、渦は新しいモデルを巻き込み、飛散は一方を吹き飛ばしてもう一方を集め、降り注ぐは新しいモデルを所定の位置へ落とし、ディゾルブは粒ごとに入れ替え、波紋は中心から広がります。"),
    ZH_HANS("交叉淡化、经由颜色、擦除、光圈和缩放作用于画面；\n其余的在3D中移动模型本身：扫过沿向上方向显露，尘埃让旧模型崩落，螺旋把新模型卷入，散开把一个吹散再聚拢另一个，如雨落下把新模型落到位，溶解逐粒替换，涟漪从中心扩散开。"),
    ZH_HANT("交叉淡化、經由顏色、擦除、光圈和縮放作用於畫面；\n其餘的在3D中移動模型本身：掃過沿向上方向顯露，塵埃讓舊模型崩落，螺旋把新模型捲入，散開把一個吹散再聚攏另一個，如雨落下把新模型落到定位，溶解逐粒替換，漣漪從中心擴散開。"),
    KO("크로스페이드, 색 전환, 와이프, 아이리스, 줌은 화면에서 작동합니다.\n나머지는 모델 자체를 3D로 움직입니다. 스윕은 위쪽 방향을 따라 드러내고, 먼지는 이전 모델을 무너뜨리고, 소용돌이는 새 모델을 휘감아 들이고, 흩어짐은 하나를 날려 보내고 다른 하나를 모으고, 비는 새 모델을 제자리에 떨어뜨리고, 디졸브는 알갱이 단위로 바꾸고, 물결은 가운데서 퍼져 나갑니다."),
    DE("Überblenden, Farbe, Wischblende, Iris und Zoom wirken auf das Bild. Die übrigen bewegen die Modelle selbst in 3D:\nein Durchlauf enthüllt entlang der Aufwärtsrichtung, Staub lässt das alte Modell zerfallen, eine Spirale wirbelt das neue herein, Zerstreuen sprengt das eine und sammelt das andere, Regen lässt das neue an seinen Platz fallen, Auflösen tauscht Korn für Korn, und eine Welle rollt von der Mitte aus."),
    FR("Fondu enchaîné, couleur, volet, iris et zoom agissent sur l'image. Les autres déplacent les modèles eux-mêmes en 3D :\nle balayage révèle le long de la verticale, la poussière effrite l'ancien modèle, la spirale fait tourbillonner le nouveau, la dispersion éclate l'un et rassemble l'autre, la pluie fait tomber le nouveau en place, le fondu granuleux les échange grain à grain et l'onde se propage depuis le centre."),
    ES("Fundido, color, cortinilla, iris y zoom actúan sobre la imagen. Las demás mueven los modelos en 3D:\nel barrido revela a lo largo de la dirección hacia arriba, el polvo desmorona el modelo anterior, la espiral hace girar el nuevo hasta su sitio, la dispersión hace estallar uno y reúne el otro, la lluvia deja caer el nuevo en su lugar, la disolución los cambia grano a grano y la onda se extiende desde el centro."),
    PT("Transição cruzada, cor, cortina, íris e zoom atuam na imagem. As demais movem os próprios modelos em 3D:\na varredura revela ao longo da direção para cima, a poeira desmancha o modelo antigo, a espiral traz o novo girando, a dispersão explode um e reúne o outro, a chuva deixa o novo cair no lugar, a dissolução troca grão a grão e a ondulação se espalha a partir do centro."),
    IT("Dissolvenza incrociata, colore, tendina, iride e zoom agiscono sull'immagine. Le altre muovono i modelli stessi in 3D:\nla scansione rivela lungo la direzione verso l'alto, la polvere sgretola il vecchio modello, la spirale fa entrare il nuovo vorticando, la dispersione fa esplodere l'uno e raccoglie l'altro, la pioggia fa cadere il nuovo al suo posto, la dissolvenza granulare li scambia grano per grano e l'increspatura si allarga dal centro."),
    NL("Overvloeien, kleur, veegovergang, iris en zoom werken op het beeld. De rest beweegt de modellen zelf in 3D:\neen veeg onthult langs de richting omhoog, stof laat het oude model afbrokkelen, een spiraal draait het nieuwe naar binnen, uiteenspatten blaast het ene uiteen en verzamelt het andere, regen laat het nieuwe op zijn plaats vallen, oplossen wisselt ze korrel voor korrel en een rimpeling rolt vanuit het midden."),
    RU("Наплыв, цвет, шторка, диафрагма и наезд работают с кадром.\nОстальные двигают сами модели в 3D: проход открывает вдоль направления вверх, пыль осыпает старую модель, спираль закручивает новую на место, разлёт разносит одну и собирает другую, дождь роняет новую на место, растворение меняет их по крупинке, а рябь расходится от середины."),
    TR("Çapraz geçiş, renk, silme, iris ve yakınlaştırma görüntü üzerinde çalışır. Diğerleri modelleri 3B'de hareket ettirir:\ntarama yukarı yön boyunca açar, toz eski modeli ufalar, sarmal yeniyi döndürerek getirir, saçılma birini dağıtıp diğerini toplar, yağmur yeniyi yerine düşürür, çözülme onları tane tane değiştirir ve dalga ortadan yayılır."));

