SS_MSG(tp_camera_help,
    EN("On: effects follow the current screen directions. Off: effects follow world up, consistently from every viewpoint."),
    JA("オン：エフェクトは現在の画面方向に従います。オフ：どの視点でもワールドの上方向に従います。"),
    ZH_HANS("开启：效果跟随当前画面方向。关闭：跟随世界向上方向，从各视点看保持一致。"),
    ZH_HANT("開啟：效果跟隨目前畫面方向。關閉：跟隨世界向上方向，從各視點看保持一致。"),
    KO("켜기: 효과가 현재 화면 방향을 따릅니다. 끄기: 모든 시점에서 동일한 월드 위쪽 방향을 따릅니다."),
    DE("An: Effekte folgen den aktuellen Bildschirmrichtungen. Aus: Sie folgen Welt-Oben, von jeder Blickrichtung gleich."),
    FR("Activé : effets orientés selon l’écran actuel. Désactivé : selon le haut du monde, identique depuis chaque point de vue."),
    ES("Activado: efectos según la pantalla actual. Desactivado: según el eje vertical del mundo, igual desde cualquier vista."),
    PT("Ativado: efeitos conforme a tela atual. Desativado: conforme o eixo vertical do mundo, igual de qualquer vista."),
    IT("Attivo: effetti secondo lo schermo attuale. Spento: secondo l’alto del mondo, uguale da ogni punto di vista."),
    NL("Aan: effecten volgen de huidige schermrichtingen. Uit: ze volgen wereld-omhoog, gelijk vanuit elk gezichtspunt."),
    RU("Вкл.: эффекты следуют текущим направлениям экрана. Выкл.: направлению вверх в мире, одинаковому с любого ракурса."),
    TR("Açık: efektler güncel ekran yönlerini izler. Kapalı: her bakış açısından aynı olan dünya yukarı yönünü izler."));

