SS_MSG(whole_path_hint,
    EN("Select every keyframe with Ctrl+A, then G or R moves the whole path -- what a model turned in the editor needs."),
    JA("Ctrl+A ですべてのキーフレームを選ぶと、G や R で経路全体を動かせます。エディターで回したモデルにはこれが必要です。"),
    ZH_HANS("用 Ctrl+A 选中所有关键帧，G 或 R 就会移动整条路径——在编辑器里转过的模型需要这样。"),
    ZH_HANT("用 Ctrl+A 選取所有關鍵影格，G 或 R 就會移動整條路徑——在編輯器裡轉過的模型需要這樣。"),
    KO("Ctrl+A로 모든 키프레임을 고르면 G나 R로 경로 전체를 움직입니다. 편집기에서 돌린 모델에는 이것이 필요합니다."),
    DE("Mit Ctrl+A jeden Keyframe wählen, dann bewegt G oder R den ganzen Weg -- das braucht ein im Editor gedrehtes Modell."),
    FR("Sélectionnez toutes les images clés avec Ctrl+A, puis G ou R déplace tout le trajet -- ce qu'il faut à un modèle tourné dans l'éditeur."),
    ES("Seleccione todos los fotogramas clave con Ctrl+A y G o R moverá todo el recorrido: lo que necesita un modelo girado en el editor."),
    PT("Selecione todos os quadros-chave com Ctrl+A e G ou R move todo o percurso -- o que um modelo girado no editor precisa."),
    IT("Seleziona tutti i fotogrammi chiave con Ctrl+A, poi G o R sposta l'intero percorso -- ciò che serve a un modello ruotato nell'editor."),
    NL("Kies elke keyframe met Ctrl+A, dan verplaatst G of R het hele pad -- wat een in de editor gedraaid model nodig heeft."),
    RU("Выберите все ключевые кадры через Ctrl+A, и G или R сдвинут весь путь — это нужно для модели, повёрнутой в редакторе."),
    TR("Ctrl+A ile tüm anahtar kareleri seçin; G ya da R bütün yolu taşır. Düzenleyicide döndürülmüş bir modelin ihtiyacı budur."));

