SS_MSG(out_codec_help,
    EN("- H.264 plays everywhere. H.265 and AV1 make a smaller file at the same quality;\n- AV1 needs a recent player, and in WebM it plays in any web browser.\n- A GIF plays anywhere a picture does, but in 256 colours and as a large file."),
    JA("- H.264 はどこでも再生できます。 H.265 と AV1 は同じ画質でファイルが小さくなります。\n- AV1 は新しいプレーヤーが必要で、WebM ならどのウェブブラウザーでも再生できます。\n- GIF は画像が表示できる場所ならどこでも再生できますが、256色で、ファイルは大きくなります。"),
    ZH_HANS("- H.264 到处都能播放。 H.265 和 AV1 在相同画质下文件更小；\n- AV1 需要较新的播放器，封装为 WebM 时任何网页浏览器都能播放。\n- GIF 在任何能显示图片的地方都能播放，但只有 256 色且文件很大。"),
    ZH_HANT("- H.264 到處都能播放。 H.265 和 AV1 在相同畫質下檔案更小；\n- AV1 需要較新的播放器，封裝為 WebM 時任何網頁瀏覽器都能播放。\n- GIF 在任何能顯示圖片的地方都能播放，但只有 256 色且檔案很大。"),
    KO("- H.264는 어디서나 재생됩니다. H.265와 AV1은 같은 화질에서 파일이 더 작습니다.\n- AV1은 최신 플레이어가 필요하고, WebM이면 어느 웹 브라우저에서나 재생됩니다.\n- GIF는 그림이 보이는 곳이면 어디서나 재생되지만 256색이고 파일이 큽니다."),
    DE("- H.264 läuft überall. H.265 und AV1 ergeben bei gleicher Qualität eine kleinere Datei;\n- AV1 braucht einen aktuellen Player und läuft als WebM in jedem Webbrowser.\n- Ein GIF läuft überall, wo ein Bild angezeigt wird, aber mit 256 Farben und als große Datei."),
    FR("- Le H.264 se lit partout. Le H.265 et l'AV1 donnent un fichier plus petit à qualité égale ;\n- l'AV1 demande un lecteur récent, et en WebM il se lit dans tout navigateur web.\n- Un GIF se lit partout où s'affiche une image, mais en 256 couleurs et dans un gros fichier."),
    ES("- H.264 se reproduce en todas partes. H.265 y AV1 dan un archivo más pequeño con la misma calidad;\n- AV1 necesita un reproductor reciente y, en WebM, se reproduce en cualquier navegador web.\n- Un GIF se reproduce donde se vea una imagen, pero con 256 colores y en un archivo grande."),
    PT("- H.264 roda em qualquer lugar. H.265 e AV1 geram um arquivo menor com a mesma qualidade;\n- o AV1 precisa de um player recente e, em WebM, roda em qualquer navegador.\n- Um GIF roda onde uma imagem aparece, mas com 256 cores e num arquivo grande."),
    IT("- H.264 si riproduce ovunque. H.265 e AV1 danno un file più piccolo a parità di qualità;\n- AV1 richiede un lettore recente e, in WebM, si riproduce in qualsiasi browser.\n- Una GIF si riproduce ovunque si veda un'immagine, ma con 256 colori e in un file grande."),
    NL("- H.264 speelt overal af. H.265 en AV1 geven een kleiner bestand bij dezelfde kwaliteit;\n- AV1 vraagt een recente speler en speelt als WebM in elke webbrowser.\n- Een GIF speelt overal waar een afbeelding wordt getoond, maar in 256 kleuren en als groot bestand."),
    RU("- H.264 воспроизводится везде. H.265 и AV1 дают файл меньше при том же качестве;\n- AV1 нужен свежий проигрыватель, а в WebM он откроется в любом браузере.\n- GIF показывается везде, где показываются картинки, но в 256 цветах и большим файлом."),
    TR("- H.264 her yerde oynatılır. H.265 ve AV1 aynı kalitede daha küçük dosya verir;\n- AV1 yeni bir oynatıcı ister ve WebM olarak her web tarayıcısında oynatılır.\n- GIF, resim gösterilen her yerde oynatılır ama 256 renkle ve büyük bir dosya olarak."));

