SS_MSG(encoder_none,
    EN("No video encoder: install ffmpeg, or render frames instead."),
    JA("動画エンコーダーがありません。ffmpeg を入れるか、代わりにフレームで書き出してください。"),
    ZH_HANS("没有视频编码器：请安装 ffmpeg，或改为渲染帧序列。"),
    ZH_HANT("沒有影片編碼器：請安裝 ffmpeg，或改為算繪影格序列。"),
    KO("동영상 인코더가 없습니다. ffmpeg을 설치하거나 대신 프레임으로 렌더링하세요."),
    DE("Kein Video-Encoder: ffmpeg installieren oder stattdessen Einzelbilder rendern."),
    FR("Pas d'encodeur vidéo : installez ffmpeg, ou rendez des images à la place."),
    ES("No hay codificador de vídeo: instale ffmpeg o renderice fotogramas en su lugar."),
    PT("Sem codificador de vídeo: instale o ffmpeg ou renderize quadros em vez disso."),
    IT("Nessun codificatore video: installa ffmpeg, oppure fai il render dei fotogrammi."),
    NL("Geen video-encoder: installeer ffmpeg, of render in plaats daarvan beelden."),
    RU("Нет видеокодировщика: установите ffmpeg или рендерите кадры."),
    TR("Video kodlayıcı yok: ffmpeg kurun ya da bunun yerine kareleri render edin."));

SS_MSG(encoder_too_large,
    EN("This GPU encodes {0} up to {1} × {2}; ffmpeg encodes this size instead."),
    JA("この GPU は {0} を {1} × {2} までしかエンコードできないので、このサイズは ffmpeg がエンコードします。"),
    ZH_HANS("此 GPU 编码 {0} 最大到 {1} × {2}；这个尺寸改由 ffmpeg 编码。"),
    ZH_HANT("此 GPU 編碼 {0} 最大到 {1} × {2}；這個尺寸改由 ffmpeg 編碼。"),
    KO("이 GPU는 {0}을 {1} × {2}까지 인코딩합니다. 이 크기는 ffmpeg이 대신 인코딩합니다."),
    DE("Diese GPU kodiert {0} bis {1} × {2}; diese Größe kodiert stattdessen ffmpeg."),
    FR("Ce GPU encode le {0} jusqu'à {1} × {2} ; cette taille sera encodée par ffmpeg."),
    ES("Esta GPU codifica {0} hasta {1} × {2}; este tamaño lo codifica ffmpeg."),
    PT("Esta GPU codifica {0} até {1} × {2}; este tamanho será codificado pelo ffmpeg."),
    IT("Questa GPU codifica {0} fino a {1} × {2}; questa dimensione la codifica ffmpeg."),
    NL("Deze GPU codeert {0} tot {1} × {2}; dit formaat codeert ffmpeg in plaats daarvan."),
    RU("Этот GPU кодирует {0} до {1} × {2}; такой размер закодирует ffmpeg."),
    TR("Bu GPU {0} biçimini en fazla {1} × {2} kodlar; bu boyutu bunun yerine ffmpeg kodlar."));

SS_MSG(encoder_too_large_none,
    EN("This GPU encodes {0} up to {1} × {2}, and ffmpeg is not installed: make it smaller, choose another format, or render frames."),
    JA("この GPU は {0} を {1} × {2} までしかエンコードできず、ffmpeg も入っていません。サイズを小さくするか、別の形式を選ぶか、フレームで書き出してください。"),
    ZH_HANS("此 GPU 编码 {0} 最大到 {1} × {2}，且未安装 ffmpeg：请减小尺寸、换一种格式或改为渲染帧序列。"),
    ZH_HANT("此 GPU 編碼 {0} 最大到 {1} × {2}，且未安裝 ffmpeg：請縮小尺寸、換一種格式或改為算繪影格序列。"),
    KO("이 GPU는 {0}을 {1} × {2}까지 인코딩하고 ffmpeg도 설치되어 있지 않습니다. 크기를 줄이거나, 다른 형식을 고르거나, 프레임으로 렌더링하세요."),
    DE("Diese GPU kodiert {0} bis {1} × {2}, und ffmpeg ist nicht installiert: kleiner machen, ein anderes Format wählen oder Einzelbilder rendern."),
    FR("Ce GPU encode le {0} jusqu'à {1} × {2}, et ffmpeg n'est pas installé : réduisez la taille, choisissez un autre format, ou rendez des images."),
    ES("Esta GPU codifica {0} hasta {1} × {2} y ffmpeg no está instalado: reduzca el tamaño, elija otro formato o renderice fotogramas."),
    PT("Esta GPU codifica {0} até {1} × {2} e o ffmpeg não está instalado: diminua o tamanho, escolha outro formato ou renderize quadros."),
    IT("Questa GPU codifica {0} fino a {1} × {2} e ffmpeg non è installato: riduci la dimensione, scegli un altro formato o fai il render dei fotogrammi."),
    NL("Deze GPU codeert {0} tot {1} × {2} en ffmpeg is niet geïnstalleerd: maak het kleiner, kies een ander formaat of render beelden."),
    RU("Этот GPU кодирует {0} до {1} × {2}, а ffmpeg не установлен: уменьшите размер, выберите другой формат или рендерите кадры."),
    TR("Bu GPU {0} biçimini en fazla {1} × {2} kodlar ve ffmpeg kurulu değil: boyutu küçültün, başka bir biçim seçin ya da kareleri render edin."));

SS_MSG(encoder_gif,
    EN("Written by this program. Keep a GIF small, 480 to 800 pixels wide, or the file gets very large."),
    JA("このプログラムが書き出します。GIF は小さく、幅 480〜800 ピクセルにしてください。でないとファイルがとても大きくなります。"),
    ZH_HANS("由本程序写出。GIF 请保持小尺寸（宽 480 到 800 像素），否则文件会非常大。"),
    ZH_HANT("由本程式寫出。GIF 請保持小尺寸（寬 480 到 800 像素），否則檔案會非常大。"),
    KO("이 프로그램이 씁니다. GIF는 가로 480~800픽셀로 작게 유지하세요. 그렇지 않으면 파일이 아주 커집니다."),
    DE("Wird von diesem Programm geschrieben. Ein GIF klein halten, 480 bis 800 Pixel breit, sonst wird die Datei sehr groß."),
    FR("Écrit par ce programme. Gardez un GIF petit, de 480 à 800 pixels de large, sinon le fichier devient très gros."),
    ES("Lo escribe este programa. Mantenga el GIF pequeño, de 480 a 800 píxeles de ancho, o el archivo será muy grande."),
    PT("Gravado por este programa. Mantenha o GIF pequeno, de 480 a 800 pixels de largura, ou o arquivo fica muito grande."),
    IT("Scritto da questo programma. Tieni la GIF piccola, larga da 480 a 800 pixel, o il file diventa molto grande."),
    NL("Door dit programma geschreven. Houd een GIF klein, 480 tot 800 pixels breed, anders wordt het bestand erg groot."),
    RU("Записывается этой программой. Делайте GIF небольшим, 480–800 пикселей в ширину, иначе файл выйдет очень большим."),
    TR("Bu program tarafından yazılır. GIF'i küçük tutun, 480 ile 800 piksel genişlikte; yoksa dosya çok büyür."));

