SS_MSG(encode_usage,
    EN("Usage: {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- GPU-encodes raw rgb24 from stdin, with rows top to bottom.\n- Writes MP4 or raw .h264, .h265 or .obu, depending on the extension.\n- --probe lists supported codecs and maximum frame sizes."),
    JA("使い方: {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- 標準入力の生 rgb24（上から下の行順）を GPU でエンコード。\n- 拡張子に応じて MP4 または生の .h264、.h265、.obu を出力。\n- --probe は対応コーデックと最大フレームサイズを表示。"),
    ZH_HANS("用法：{0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- GPU 编码标准输入的原始 rgb24，行从上到下。\n- 按扩展名输出 MP4 或原始 .h264、.h265、.obu。\n- --probe 列出支持的编解码器和最大帧尺寸。"),
    ZH_HANT("用法：{0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- GPU 編碼標準輸入的原始 rgb24，列從上到下。\n- 按副檔名輸出 MP4 或原始 .h264、.h265、.obu。\n- --probe 列出支援的編解碼器與最大影格尺寸。"),
    KO("사용법: {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- 표준 입력의 원시 rgb24를 GPU로 인코딩합니다. 행은 위에서 아래 순서입니다.\n- 확장자에 따라 MP4 또는 원시 .h264, .h265, .obu를 씁니다.\n- --probe는 지원 코덱과 최대 프레임 크기를 표시합니다."),
    DE("Aufruf: {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- GPU kodiert rohes rgb24 von stdin, Zeilen von oben nach unten.\n- Ausgabe je Endung: MP4 oder roh .h264, .h265 oder .obu.\n- --probe listet Codecs und maximale Bildgrößen."),
    FR("utilisation : {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- Encode sur GPU le rgb24 brut de stdin, lignes du haut vers le bas.\n- Sortie selon l’extension : MP4 ou flux brut .h264, .h265 ou .obu.\n- --probe liste les codecs et tailles maximales."),
    ES("uso: {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- Codifica en GPU rgb24 crudo de stdin, filas de arriba abajo.\n- Según extensión, escribe MP4 o flujo crudo .h264, .h265 u .obu.\n- --probe muestra códecs y tamaños máximos."),
    PT("uso: {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- Codifica na GPU rgb24 bruto de stdin, linhas de cima para baixo.\n- Pela extensão, grava MP4 ou fluxo bruto .h264, .h265 ou .obu.\n- --probe lista codecs e tamanhos máximos."),
    IT("uso: {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- Codifica su GPU rgb24 grezzo da stdin, righe dall’alto al basso.\n- Dall’estensione scrive MP4 o flusso grezzo .h264, .h265 o .obu.\n- --probe elenca codec e dimensioni massime."),
    NL("gebruik: {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- Codeert ruwe rgb24 van stdin op de GPU, rijen van boven naar beneden.\n- Op extensie: MP4 of ruwe .h264, .h265 of .obu.\n- --probe toont codecs en maximale framegrootten."),
    RU("использование: {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- Кодирует на GPU сырой rgb24 из stdin, строки сверху вниз.\n- По расширению пишет MP4 или сырой поток .h264, .h265 либо .obu.\n- --probe выводит кодеки и максимальные размеры кадра."),
    TR("kullanım: {0} --size WIDTHxHEIGHT --fps RATE [--codec h264|h265|av1] [--quality 0|1|2] [--spherical] -o FILE\n- stdin’den ham rgb24 akışını GPU ile kodlar. Satırlar yukarıdan aşağıdır.\n- Uzantıya göre MP4 veya ham .h264, .h265, .obu yazar.\n- --probe kodekleri ve en büyük kare boyutlarını gösterir."));

