SS_MSG(hint_idle,
    EN("K adds a keyframe from the view. Click a camera to select it. Space plays, 0 looks through the camera, numeric-pad .\nframes the cameras."),
    JA("K でビューからキーフレームを追加。 カメラをクリックで選択。 Space で再生、0 でカメラから見る、テンキーの .\nでカメラを画面に収めます。"),
    ZH_HANS("K 从视图添加关键帧。点击相机选中它。Space 播放，0 从相机看，数字键盘 . 让相机都进入视野。"),
    ZH_HANT("K 從視圖新增關鍵影格。點擊相機選取它。Space 播放，0 從相機看，數字鍵盤 . 讓相機都進入視野。"),
    KO("K는 뷰에서 키프레임 추가. 카메라를 클릭해 선택.\nSpace는 재생, 0은 카메라로 보기, 숫자 패드 .는 카메라가 화면에 들어오게 합니다."),
    DE("K fügt einen Keyframe aus der Ansicht hinzu. Eine Kamera anklicken, um sie zu wählen.\nSpace spielt ab, 0 schaut durch die Kamera, Ziffernblock . holt die Kameras ins Bild."),
    FR("K ajoute une image clé depuis la vue. Cliquez une caméra pour la choisir. Space lit, 0 regarde par la caméra, le .\ndu pavé numérique cadre les caméras."),
    ES("K añade un fotograma clave desde la vista. Haga clic en una cámara para elegirla.\nSpace reproduce, 0 mira por la cámara, el . del teclado numérico encuadra las cámaras."),
    PT("K adiciona um quadro-chave a partir da vista. Clique numa câmera para escolhê-la.\nSpace reproduz, 0 olha pela câmera, o . do teclado numérico enquadra as câmeras."),
    IT("K aggiunge un fotogramma chiave dalla vista. Fai clic su una camera per sceglierla.\nSpace riproduce, 0 guarda dalla camera, il . del tastierino numerico inquadra le camere."),
    NL("K voegt een keyframe toe vanuit het beeld. Klik op een camera om hem te kiezen.\nSpace speelt af, 0 kijkt door de camera, . op het numerieke toetsenblok brengt de camera's in beeld."),
    RU("K добавляет ключевой кадр из вида. Щелчок по камере выбирает её.\nSpace — воспроизведение, 0 — взгляд через камеру, . на цифровой клавиатуре показывает все камеры."),
    TR("K görünümden anahtar kare ekler. Seçmek için bir kameraya tıklayın.\nSpace oynatır, 0 kameradan bakar, sayısal tuş takımındaki . kameraları ekrana sığdırır."));

SS_MSG(hint_selected,
    EN("- G move; R turn; S field of view (multiple: spread). X/Delete removes keys, keeping the path.\n- T choose look target; numpad . frame keys.\n- Ctrl+A select all; Ctrl+D deselect."),
    JA("- G移動、R回転、S画角（複数時は広がり）。X/Deleteで経路を保ってキー削除。\n- Tで注視点選択、テンキー.でキーを画面に収める。\n- Ctrl+A全選択、Ctrl+D選択解除。"),
    ZH_HANS("- G 移动、R 旋转、S 视场角（多选为间距）；X/Delete 删关键帧并保持路径。\n- T 选注视点；小键盘 . 框显关键帧。\n- Ctrl+A 全选；Ctrl+D 取消选择。"),
    ZH_HANT("- G 移動、R 旋轉、S 視角（多選為間距）；X/Delete 刪關鍵影格並保持路徑。\n- T 選注視點；數字鍵盤 . 框顯關鍵影格。\n- Ctrl+A 全選；Ctrl+D 取消選取。"),
    KO("- G 이동, R 회전, S 화각(여러 개: 간격). X/Delete는 경로를 유지하며 키를 삭제합니다.\n- T 시선 대상, 숫자패드 . 키 전체 보기.\n- Ctrl+A 전체 선택, Ctrl+D 선택 해제."),
    DE("- G bewegen; R drehen; S Sichtfeld (mehrere: Abstand). X/Delete löscht Keys und erhält den Weg.\n- T Blickziel; Ziffernblock . Keys einrahmen.\n- Ctrl+A alle; Ctrl+D keine wählen."),
    FR("- G déplacer ; R tourner ; S champ de vue (plusieurs : écart). X/Delete retire les clés, garde le trajet.\n- T cible du regard ; pavé . cadre les clés.\n- Ctrl+A tout sélectionner ; Ctrl+D désélectionner."),
    ES("- G mover; R girar; S campo de visión (varias: separación). X/Delete borra claves, conserva ruta.\n- T objetivo; teclado numérico . encuadra claves.\n- Ctrl+A todas; Ctrl+D ninguna."),
    PT("- G mover; R girar; S campo de visão (várias: distância). X/Delete apaga chaves e mantém caminho.\n- T alvo; teclado numérico . enquadra chaves.\n- Ctrl+A todas; Ctrl+D nenhuma."),
    IT("- G sposta; R ruota; S campo visivo (più chiavi: distanza). X/Delete elimina chiavi, conserva percorso.\n- T bersaglio; tastierino . inquadra chiavi.\n- Ctrl+A tutte; Ctrl+D nessuna."),
    NL("- G verplaats; R draai; S beeldhoek (meerdere: spreiding). X/Delete wist keys en behoudt pad.\n- T kijkdoel; numpad . kadreert keys.\n- Ctrl+A alles; Ctrl+D niets selecteren."),
    RU("- G двигать; R вращать; S угол обзора (несколько: разброс). X/Delete удаляет ключи, сохраняя путь.\n- T цель взгляда; numpad . вписывает ключи.\n- Ctrl+A всё; Ctrl+D снять выбор."),
    TR("- G taşı; R döndür; S görüş açısı (çoklu: açıklık). X/Delete anahtarları siler, yolu korur.\n- T bakış hedefi; sayısal . anahtarları çerçeveler.\n- Ctrl+A tümü; Ctrl+D seçimi kaldır."));

SS_MSG(hint_op,
    EN("Move the mouse. X, Y or Z locks an axis, a number is typed, click or Enter finishes, right-click or Esc cancels."),
    JA("マウスを動かします。X・Y・Z で軸を固定、数値を入力可、クリックか Enter で確定、右クリックか Esc で取り消し。"),
    ZH_HANS("移动鼠标。X、Y 或 Z 锁定轴，可输入数值，点击或 Enter 完成，右键或 Esc 取消。"),
    ZH_HANT("移動滑鼠。X、Y 或 Z 鎖定軸，可輸入數值，點擊或 Enter 完成，右鍵或 Esc 取消。"),
    KO("마우스를 움직이세요. X, Y, Z로 축 고정, 숫자 입력 가능, 클릭이나 Enter로 완료, 오른쪽 클릭이나 Esc로 취소."),
    DE("Die Maus bewegen. X, Y oder Z sperrt eine Achse, eine Zahl kann getippt werden, Klick oder Enter beendet, Rechtsklick oder Esc bricht ab."),
    FR("Bougez la souris. X, Y ou Z verrouille un axe, un nombre se tape, clic ou Enter termine, clic droit ou Esc annule."),
    ES("Mueva el ratón. X, Y o Z bloquea un eje, se puede escribir un número, clic o Enter termina, clic derecho o Esc cancela."),
    PT("Mova o mouse. X, Y ou Z trava um eixo, dá para digitar um número, clique ou Enter conclui, clique direito ou Esc cancela."),
    IT("Muovi il mouse. X, Y o Z blocca un asse, si può digitare un numero, clic o Enter conclude, clic destro o Esc annulla."),
    NL("Beweeg de muis. X, Y of Z vergrendelt een as, een getal kan getypt worden, klik of Enter voltooit, rechtsklik of Esc annuleert."),
    RU("Двигайте мышь. X, Y или Z фиксируют ось, можно ввести число, щелчок или Enter — готово, правый щелчок или Esc — отмена."),
    TR("Fareyi hareket ettirin. X, Y ya da Z bir ekseni kilitler, sayı yazılabilir, tıklama ya da Enter bitirir, sağ tıklama ya da Esc iptal eder."));

SS_MSG(hint_op_fov,
    EN("Move the mouse to widen or narrow the view. A number is a factor, click or Enter finishes, Esc cancels."),
    JA("マウスを動かして視野を広げたり狭めたりします。数値は倍率、クリックか Enter で確定、Esc で取り消し。"),
    ZH_HANS("移动鼠标以放宽或收窄视野。输入的数值是倍数，点击或 Enter 完成，Esc 取消。"),
    ZH_HANT("移動滑鼠以放寬或收窄視野。輸入的數值是倍數，點擊或 Enter 完成，Esc 取消。"),
    KO("마우스를 움직여 시야를 넓히거나 좁힙니다. 숫자는 배율, 클릭이나 Enter로 완료, Esc로 취소."),
    DE("Die Maus bewegen, um das Bild weiter oder enger zu machen. Eine Zahl ist ein Faktor, Klick oder Enter beendet, Esc bricht ab."),
    FR("Bougez la souris pour élargir ou resserrer la vue. Un nombre est un facteur, clic ou Enter termine, Esc annule."),
    ES("Mueva el ratón para abrir o cerrar la vista. Un número es un factor, clic o Enter termina, Esc cancela."),
    PT("Mova o mouse para abrir ou fechar a vista. Um número é um fator, clique ou Enter conclui, Esc cancela."),
    IT("Muovi il mouse per allargare o stringere la vista. Un numero è un fattore, clic o Enter conclude, Esc annulla."),
    NL("Beweeg de muis om het beeld wijder of nauwer te maken. Een getal is een factor, klik of Enter voltooit, Esc annuleert."),
    RU("Двигайте мышь, чтобы расширить или сузить вид. Число — множитель, щелчок или Enter — готово, Esc — отмена."),
    TR("Görünümü genişletmek ya da daraltmak için fareyi hareket ettirin. Sayı bir çarpandır, tıklama ya da Enter bitirir, Esc iptal eder."));

SS_MSG(hint_pick,
    EN("Click the point the camera should look at. Right-click or Esc cancels."),
    JA("カメラに見せたい点をクリックします。右クリックか Esc で取り消し。"),
    ZH_HANS("点击相机要看的点。右键或 Esc 取消。"),
    ZH_HANT("點擊相機要看的點。右鍵或 Esc 取消。"),
    KO("카메라가 바라볼 점을 클릭하세요. 오른쪽 클릭이나 Esc로 취소."),
    DE("Den Punkt anklicken, auf den die Kamera schauen soll. Rechtsklick oder Esc bricht ab."),
    FR("Cliquez le point que la caméra doit regarder. Clic droit ou Esc annule."),
    ES("Haga clic en el punto al que debe mirar la cámara. Clic derecho o Esc cancela."),
    PT("Clique no ponto para onde a câmera deve olhar. Clique direito ou Esc cancela."),
    IT("Fai clic sul punto che la camera deve guardare. Clic destro o Esc annulla."),
    NL("Klik op het punt waar de camera naar moet kijken. Rechtsklik of Esc annuleert."),
    RU("Щёлкните по точке, на которую должна смотреть камера. Правый щелчок или Esc — отмена."),
    TR("Kameranın bakacağı noktaya tıklayın. Sağ tıklama ya da Esc iptal eder."));


