SS_MSG(tl_play_help,
    EN("Play the camera move (Space).\nHome and End jump to the ends, comma and period step one frame, Page Up and Page Down go from keyframe to keyframe."),
    JA("カメラの動きを再生します（Space）。\nHome と End で端へ、カンマとピリオドで1フレームずつ、Page Up と Page Down でキーフレームからキーフレームへ移ります。"),
    ZH_HANS("播放相机运动（Space）。Home 和 End 跳到两端，逗号和句号逐帧移动，Page Up 和 Page Down 在关键帧之间跳转。"),
    ZH_HANT("播放相機運動（Space）。Home 和 End 跳到兩端，逗號和句號逐格移動，Page Up 和 Page Down 在關鍵影格之間跳轉。"),
    KO("카메라 움직임을 재생합니다(Space).\nHome과 End는 양 끝으로, 쉼표와 마침표는 한 프레임씩, Page Up과 Page Down은 키프레임에서 키프레임으로 갑니다."),
    DE("Die Kamerafahrt abspielen (Space). Home und End springen an die Enden, Komma und Punkt gehen ein Bild weiter, Page Up und Page Down von Keyframe zu Keyframe."),
    FR("Lire le mouvement de caméra (Space). Home et End sautent aux extrémités, virgule et point avancent d'une image, Page Up et Page Down vont d'image clé en image clé."),
    ES("Space reproduce. Home/End: extremos; coma/punto: un fotograma atrás/adelante; Page Up/Page Down: clave anterior/siguiente."),
    PT("Reproduzir o movimento de câmera (Space). Home e End saltam para as pontas, vírgula e ponto avançam um quadro, Page Up e Page Down vão de quadro-chave em quadro-chave."),
    IT("Riproduci il movimento di camera (Space). Home e End saltano agli estremi, virgola e punto avanzano di un fotogramma, Page Up e Page Down vanno da un fotogramma chiave all'altro."),
    NL("De camerabeweging afspelen (Space). Home en End springen naar de uiteinden, komma en punt gaan één beeld verder, Page Up en Page Down gaan van keyframe naar keyframe."),
    RU("Воспроизвести движение камеры (Space).\nHome и End — к краям, запятая и точка — на кадр, Page Up и Page Down — от ключевого кадра к ключевому."),
    TR("Kamera hareketini oynat (Space). Home ve End uçlara atlar, virgül ve nokta bir kare ilerler, Page Up ve Page Down anahtar kareden anahtar kareye gider."));

