SS_MSG(tl_track_help,
    EN("Click to move the playhead.\n- Drag a keyframe to retime it. Shift-click selects a range and Ctrl-click adds a key.\n- Double-click adds a keyframe. Right-click opens its menu.\n- Drag shot handles to adjust starts, transitions and exits."),
    JA("クリックで再生ヘッドを移動。キーフレームをドラッグで時刻を変更、Shift クリックで範囲選択、Ctrl クリックで1つ追加。\n- ダブルクリックでそこにキーフレームを追加、キーフレームを右クリックでその他の操作。\n- その下のショットでは、ショットの開始、トランジションの終わり、独自の退場の始まりと終わりをドラッグできます。"),
    ZH_HANS("点击移动播放头。拖动关键帧改变其时间； Shift 点击选中一段关键帧，Ctrl 点击多选一个。双击在该处添加关键帧，右键点击关键帧查看更多操作。\n在下方的镜头里，可以拖动镜头的开始、转场的结束，以及它自己离场的开始和结束。"),
    ZH_HANT("點擊移動播放頭。拖曳關鍵影格改變其時間； Shift 點擊選取一段關鍵影格，Ctrl 點擊多選一個。按兩下在該處新增關鍵影格，右鍵點擊關鍵影格查看更多操作。\n在下方的鏡頭裡，可以拖曳鏡頭的開始、轉場的結束，以及它自己離場的開始和結束。"),
    KO("클릭하면 재생 헤드가 옮겨집니다. 키프레임을 드래그해 시간을 바꾸고, Shift 클릭으로 구간 선택, Ctrl 클릭으로 하나 더 선택합니다.\n- 더블 클릭하면 그 자리에 키프레임을 추가하고, 키프레임을 오른쪽 클릭하면 더 많은 작업이 나옵니다.\n- 그 아래 샷에서는 샷의 시작, 전환의 끝, 자기만의 퇴장의 시작과 끝을 드래그합니다."),
    DE("Klicken setzt den Abspielkopf. Einen Keyframe ziehen ändert seine Zeit; Shift-Klick wählt eine Reihe von Keyframes, Ctrl-Klick einen weiteren.\n- Doppelklick fügt dort einen Keyframe hinzu, Rechtsklick auf einen Keyframe für mehr.\n- In den Einstellungen darunter lassen sich der Beginn einer Einstellung, das Ende ihres Übergangs sowie Beginn und Ende ihres eigenen Abgangs ziehen."),
    FR("Cliquez pour placer la tête de lecture. Glissez une image clé pour changer son temps ; Shift-clic choisit une suite d'images clés, Ctrl-clic une de plus.\n- Double-clic ajoute une image clé à cet endroit, clic droit sur une image clé pour plus.\n- Dans les plans en dessous, glissez le début d'un plan, la fin de sa transition, et le début et la fin de sa propre sortie."),
    ES("Haga clic para mover el cabezal. Arrastre un fotograma clave para cambiar su tiempo; Shift-clic elige una serie de fotogramas clave, Ctrl-clic uno más.\n- Doble clic añade uno ahí, clic derecho en un fotograma clave para más.\n- En las tomas de debajo, arrastre dónde empieza una toma, dónde acaba su transición y dónde empieza y acaba su propia salida."),
    PT("Clique para mover o cursor de reprodução. Arraste um quadro-chave para mudar seu tempo; Shift-clique escolhe uma sequência de quadros-chave, Ctrl-clique mais um.\n- Clique duplo adiciona um ali, clique direito num quadro-chave para mais.\n- Nas tomadas abaixo, arraste onde uma tomada começa, onde termina a sua transição e onde começa e termina a sua própria saída."),
    IT("Fai clic per spostare la testina. Trascina un fotogramma chiave per cambiarne il tempo; Shift-clic sceglie una serie di fotogrammi chiave, Ctrl-clic uno in più.\n- Doppio clic ne aggiunge uno lì, clic destro su un fotogramma chiave per altro.\n- Nelle inquadrature sotto, trascina dove inizia un'inquadratura, dove finisce la sua transizione e dove inizia e finisce la sua uscita."),
    NL("Klik om de afspeelkop te verplaatsen. Sleep een keyframe om de tijd te veranderen; Shift-klik kiest een reeks keyframes, Ctrl-klik er één bij.\n- Dubbelklik voegt daar een keyframe toe, rechtsklik op een keyframe voor meer.\n- In de shots eronder sleep je waar een shot begint, waar zijn overgang eindigt, en waar zijn eigen vertrek begint en eindigt."),
    RU("Щелчок переносит указатель воспроизведения. Перетащите ключевой кадр, чтобы сменить его время; Shift-щелчок выбирает ряд кадров, Ctrl-щелчок — ещё один.\n- Двойной щелчок добавляет кадр в этом месте, правый щелчок по кадру — другие действия.\n- В планах ниже перетаскиваются начало плана, конец его перехода, а также начало и конец его собственного ухода."),
    TR("Oynatma imlecini taşımak için tıklayın. Zamanını değiştirmek için bir anahtar kareyi sürükleyin; Shift-tıklama bir dizi anahtar kare, Ctrl-tıklama bir tane daha seçer.\n- Çift tıklama oraya bir anahtar kare ekler, fazlası için bir anahtar kareye sağ tıklayın.\n- Alttaki çekimlerde bir çekimin başladığı yeri, geçişinin bittiği yeri ve kendi çıkışının başladığı ve bittiği yeri sürükleyin."));

