SS_MSG(pv_help,
    EN("Choose where to show the camera preview.\n- Corner: drag the inner corner to resize or double-click for full preview.\n- Side by side: drag the divider.\n- Full preview: drag the image to steer the camera."),
    JA("カメラ自身の絵をどこに表示するか: ビューポートの隅（内側の角をドラッグで大きさ変更、ダブルクリックで全体プレビュー）、ビューポートと並べて（間のバーをドラッグ）、または単独で。\n全体プレビューでは絵をドラッグしてカメラを操作します。"),
    ZH_HANS("相机自己的画面显示在哪里：视口的角落（拖动其内角调整大小，双击进入完整预览）、与视口并排（拖动中间的分隔条），或单独显示。\n在完整预览中，拖动画面来操纵相机。"),
    ZH_HANT("相機自己的畫面顯示在哪裡：檢視區的角落（拖曳其內角調整大小，按兩下進入完整預覽）、與檢視區並排（拖曳中間的分隔條），或單獨顯示。\n在完整預覽中，拖曳畫面來操縱相機。"),
    KO("카메라 자신의 그림을 어디에 보여 줄지: 뷰포트 구석(안쪽 모서리를 드래그해 크기 조절, 더블 클릭하면 전체 미리보기), 뷰포트와 나란히(사이의 막대를 드래그), 또는 단독으로.\n전체 미리보기에서는 그림을 드래그해 카메라를 조종합니다."),
    DE("Wo das Bild der Kamera selbst gezeigt wird: in einer Ecke des Fensters (die innere Ecke ziehen ändert die Größe, Doppelklick öffnet die volle Vorschau), neben dem Fenster (den Balken dazwischen ziehen) oder allein.\nIn der vollen Vorschau das Bild ziehen, um die Kamera zu lenken."),
    FR("Où s'affiche l'image de la caméra elle-même : dans un coin de la vue (glissez son coin intérieur pour la redimensionner, double-clic pour l'aperçu complet), à côté de la vue (glissez la barre entre les deux), ou seule.\nDans l'aperçu complet, glissez l'image pour piloter la caméra."),
    ES("Dónde se muestra la imagen de la propia cámara: en una esquina de la vista (arrastre su esquina interior para cambiar el tamaño, doble clic para la vista previa completa), al lado de la vista (arrastre la barra entre ambas) o sola.\nEn la vista previa completa, arrastre la imagen para dirigir la cámara."),
    PT("Onde a imagem da própria câmera aparece: num canto da vista (arraste o canto interno para redimensionar, clique duplo para a prévia completa), ao lado da vista (arraste a barra entre elas) ou sozinha.\nNa prévia completa, arraste a imagem para conduzir a câmera."),
    IT("Dove si vede l'immagine della camera stessa: in un angolo della vista (trascina l'angolo interno per ridimensionarla, doppio clic per l'anteprima intera), affiancata alla vista (trascina la barra tra le due) o da sola.\nNell'anteprima intera, trascina l'immagine per guidare la camera."),
    NL("Waar het eigen beeld van de camera staat: in een hoek van het venster (sleep de binnenhoek om het formaat te wijzigen, dubbelklik voor het volledige voorbeeld), naast het venster (sleep de balk ertussen) of alleen.\nIn het volledige voorbeeld sleep je het beeld om de camera te sturen."),
    RU("Где показывать собственную картинку камеры: в углу окна (перетащите внутренний угол, чтобы изменить размер, двойной щелчок — полный просмотр), рядом с окном (перетащите полосу между ними) или отдельно.\nВ полном просмотре перетаскивайте картинку, чтобы вести камеру."),
    TR("Kameranın kendi görüntüsünün gösterildiği yer: görünümün bir köşesinde (boyutlandırmak için iç köşesini sürükleyin, tam önizleme için çift tıklayın), görünümün yanında (aradaki çubuğu sürükleyin) ya da tek başına.\nTam önizlemede kamerayı yönlendirmek için görüntüyü sürükleyin."));

SS_MSG(pv_scale_help,
    EN("The preview's size against the real output: smaller is quicker to redraw."),
    JA("実際の出力に対するプレビューの大きさです。小さいほど描き直しが速くなります。"),
    ZH_HANS("预览相对实际输出的大小：越小重绘越快。"),
    ZH_HANT("預覽相對實際輸出的大小：越小重繪越快。"),
    KO("실제 출력에 대한 미리보기의 크기입니다. 작을수록 다시 그리기가 빠릅니다."),
    DE("Die Größe der Vorschau gegenüber der echten Ausgabe: kleiner zeichnet schneller neu."),
    FR("La taille de l'aperçu par rapport à la vraie sortie : plus petit se redessine plus vite."),
    ES("El tamaño de la vista previa frente a la salida real: más pequeña se redibuja antes."),
    PT("O tamanho da prévia em relação à saída real: menor redesenha mais rápido."),
    IT("La dimensione dell'anteprima rispetto all'output reale: più piccola si ridisegna prima."),
    NL("De grootte van het voorbeeld ten opzichte van de echte uitvoer: kleiner tekent sneller opnieuw."),
    RU("Размер превью относительно настоящего вывода: чем меньше, тем быстрее перерисовка."),
    TR("Önizlemenin gerçek çıktıya göre boyutu: küçük olan daha hızlı yeniden çizilir."));

