SS_MSG(pv_through_hint,
    EN("Camera view, {0} × {1}. Drag to turn, right-drag to slide, wheel to move, Ctrl and wheel to zoom."),
    JA("カメラビュー {0} × {1}。ドラッグで向きを変え、右ドラッグで平行移動、ホイールで前後、Ctrl とホイールでズーム。"),
    ZH_HANS("相机视图，{0} × {1}。拖动转向，右键拖动平移，滚轮前后移动，Ctrl 加滚轮缩放。"),
    ZH_HANT("相機視圖，{0} × {1}。拖曳轉向，右鍵拖曳平移，滾輪前後移動，Ctrl 加滾輪縮放。"),
    KO("카메라 뷰, {0} × {1}. 드래그로 방향 전환, 오른쪽 드래그로 평행 이동, 휠로 앞뒤 이동, Ctrl과 휠로 줌."),
    DE("Kamerabild, {0} × {1}. Ziehen dreht, Rechtsziehen verschiebt, das Mausrad fährt vor und zurück, Ctrl und Mausrad zoomt."),
    FR("Vue caméra, {0} × {1}. Glisser pour tourner, glisser-droit pour décaler, molette pour avancer, Ctrl et molette pour zoomer."),
    ES("Vista de cámara, {0} × {1}. Arrastre para girar, arrastre con el botón derecho para desplazar, rueda para avanzar, Ctrl y rueda para el zoom."),
    PT("Vista da câmera, {0} × {1}. Arraste para girar, arraste com o botão direito para deslocar, roda para avançar, Ctrl e roda para o zoom."),
    IT("Vista camera, {0} × {1}. Trascina per girare, trascina col destro per traslare, rotellina per muoverti, Ctrl e rotellina per lo zoom."),
    NL("Camerabeeld, {0} × {1}. Slepen draait, rechts slepen schuift, het wiel beweegt, Ctrl en wiel zoomt."),
    RU("Вид камеры, {0} × {1}. Перетаскивание поворачивает, правой кнопкой — сдвиг, колесо — движение, Ctrl и колесо — зум."),
    TR("Kamera görünümü, {0} × {1}. Sürükleyerek döndürün, sağ sürükleyerek kaydırın, tekerlekle ilerleyin, Ctrl ve tekerlekle yakınlaştırın."));

